window.POEM_DB=window.POEM_DB||{};POEM_DB["song_048"]={"n":"洪适","dyn":"宋","poems":[{"t":"番禺调笑 其十 清远峡","f":"词","c":["明月。","舟初歇。","三峡重过惊久别。","玉环留与人间说。","诗罢离肠千结。","相思朝暮流泉咽。","雾锁青山愁绝。"]},{"t":"雨中泊舟萧山县驿","f":"七言律诗","c":["端居无策散闲愁，聊作人间汗漫游。","晚笛随风来倦枕，春潮带雨送孤舟。","店家菰饭香初熟，市担莼丝滑欲流。","自笑劳生成底事，黄尘陌上雪蒙头。"]},{"t":"盘洲杂韵上 木兰","f":"五言绝句","c":["未识春风面，先闻乐府名。","洗妆侬出塞，进艇客登瀛。"]},{"t":"十二时慢","f":"词","c":["庭有燎，叠鼓鸣鼍。","更问夜如何。","信星彪列，天象森罗。","虞旦閟宫毕，觞清庙，浆柘尊牺继猗那。","嘉颂可同科。","扈圣万肩摩。","饬躬三宿，泰畤缛仪多。","丘泽合，岳渎从曦娥。","神光烛、云车风马，芝作盖，玉为珂。","奉瑄成礼，燔柴竣事，休嘉砰，隐丹阙，湛恩波。","共愿乾坤隤祉，边鄙投戈。","覆盂连瀚海，洗甲挽天河。","欣欣喜色，长遇六龙过。","奏云和。","三春荐嘉禾。"]},{"t":"卜算子 席上赠瞻明","f":"词","c":["修竹拂疏棂，淡月侵凉榭。","四畔青山进好风，金鸭香煤灺。","宝唾粲珠玑，长袖飘兰麝。","莫问更楼夜若何，且结高阳社。"]},{"t":"卜算子 太守席上作","f":"词","c":["五凤望中仙，五马人间贵。","舞态歌声尽出群，乌鹊巡檐喜。","昨夜值狂风，痛饮全无味。","说与谯门漫打更，却怕催归骑。"]},{"t":"千秋岁 代上帅宅生日","f":"词","c":["颜朱鬓绿。","天与穰穰福。","旄钺贵，崇汤沐。","华轩鱼映锦，紫诰鸾回幅。","为寿处，玻璃凿落斟醽醁。","瑞雾蟠华屋。","露浥秋兰馥。","香篆起，歌裾簇。","衣斑丹穴凤，色润东床玉。","鸾共鹤，年年来听神仙曲。"]},{"t":"隆兴二年南郊鼓吹曲 六州歌头","f":"词","c":["严更永，今夕是何年。","玉衡正，钩陈灿，天宇起祥烟。","协风应、江海安澜。","重规仍叠矩，圣主乘乾。","尧授舜、盛事光前。","称寿玉卮边。","三年亲祀，一阳回律，八乡承宇，觚陛紫为坛。","仰天颜。","斋居寂，诚心肃，礼容专。","存钟石，约舆卫，五辂不求全。","听金钥、虎旅无眠。","俨千官。","须期显。","相嘉笾。","一人俭德动天渊。","费减大农钱。","神示格，宗祧燕。","人民悦，祉福正绵绵。"]},{"t":"长相思 其二","f":"词","c":["柳青青。","酒清清。","雨脚涔涔忆渭城。","一尊和泪倾。","山青青。","水清清。","水阔山重不计程。","愁堆长短亭。"]},{"t":"长相思 其一","f":"词","c":["朝思归。","暮思归。","塞雁三年不见飞。","断肠天一涯。","千思归。","万思归。","梦到窗前拂淡眉。","觉来双泪垂。"]},{"t":"生查子 其五","f":"五言律诗","c":["四月到盘洲，长是黄梅雨。","屐齿满莓苔，避湿开新路。","极望绿阴成，不见乌飞处。","云采列奇峰，绝胜看庐阜。"]},{"t":"生查子 其八","f":"五言律诗","c":["七月到盘洲，枕簟新凉早。","岸曲侧黄葵，沙际排红蓼。","团团歌扇疏，整整炉烟袅。","环坐待横参，要乞蛛丝巧。"]},{"t":"生查子 其十二","f":"五言律诗","c":["子月到盘洲，日影长添线。","水退露溪痕，风急寒芦战。","终日倚枯藤，细看浮云变。","洲畔有圆沙，招尽云边雁。"]},{"t":"生查子 其七","f":"五言律诗","c":["六月到盘洲，水阁盟鸥鹭。","面面纳清风，不受人间暑。","彩舫下垂杨，深入荷花去。","浅笑擘莲蓬，去却中心苦。"]},{"t":"生查子 收灯日次李举之韵","f":"五言律诗","c":["廉纤小雨来，噤瘆轻寒乍。","丝竹送迎时，灯火阑珊夜。","铜壶漏故迟，银烛花频灺。","怀我独醒人，健笔方飞洒。"]},{"t":"生查子 其二","f":"五言律诗","c":["正月到盘洲，解冻东风至。","便有浴鸥飞，时见潜鳞起。","高柳送青来，春在长林里。","绿萼一枝梅，端是花中瑞。"]},{"t":"生查子 其六","f":"五言律诗","c":["五月到盘洲，照眼红巾蹙。","句引石榴裙，一唱仙翁曲。","藕步进新船，斗楫飞云速。","此际独醒难，一一金钟覆。"]},{"t":"生查子 其一 盘洲曲","f":"五言律诗","c":["带郭得盘洲，胜处双溪水。","月榭间风亭，叠嶂横空翠。","团栾情话时，三径参差是。","听我一年词，对景休辞醉。"]},{"t":"生查子 其十一","f":"五言律诗","c":["十月到盘洲，小小阳春节。","晚菊自争妍，谁管人心别。","木末簇芙蓉，禁得霜如雪。","心赏四时同，不与痴人说。"]},{"t":"生查子","f":"五言律诗","c":["桃疏蝶惜香，柳困莺惊絮。","日影过帘旌，多少愁情绪。","红惨武陵溪，绿暗章台路。","春色似行人，无意花间住。"]},{"t":"生查子 其十三","f":"五言律诗","c":["腊月到盘洲，寒重层冰结。","试去探梅花，休把南枝折。","顷刻暗同云，不觉红炉热。","隐隐绿蓑翁，独钓寒江雪。"]},{"t":"生查子 其十四","f":"五言律诗","c":["一岁会盘洲，月月生查子。","弟劝复兄酬，举案灯花喜。","曲终人半酣，添酒留罗绮。","车马不须喧，且听三更未。"]},{"t":"生查子 其九","f":"五言律诗","c":["八月到盘洲，柳外寒蝉懒。","一掬木犀花，泛泛玻璃盏。","蟾桂十分明，远近秋毫见。","举酒劝嫦娥，长使清光满。"]},{"t":"生查子 其一 姚母寿席，以龟游莲叶杯酌酒","f":"五言律诗","c":["碧涧有神龟，千岁游莲叶。","七十古来稀，寿母杯频接。","绣衣牵彩衣，喜庆相重叠。","龟紫看孙曾，鹤发何须镊。"]},{"t":"生查子 其一","f":"五言律诗","c":["九月到盘洲，华发惊霜叶。","缓步绕东篱，香蕊金重叠。","橘绿又橙黄，四老相迎接。","好处不宜休，莫放清尊歇。"]},{"t":"生查子 其四","f":"五言律诗","c":["三月到盘洲，九曲清波聚。","修竹荫流觞，秀叶题佳句。","红紫渐阑珊，恋恋莺花主。","芍药拥芳蹊，未放春归去。"]},{"t":"生查子 其二 枕上作","f":"五言律诗","c":["贪看端木花，难办销金帐。","庭下舞琼瑶，飞到须眉上。","衰病不禁寒，对景频惆怅。","梦寐到凌风，倚著青藜杖。"]},{"t":"生查子 其三","f":"五言律诗","c":["二月到盘洲，繁缬盈千萼。","恰恰早莺啼，一羽黄金落。","花边自在行，临水还寻壑。","步步肯相随，独有苍梧鹤。"]},{"t":"好事近","f":"词","c":["春意渐盈盈，窗外小桃堪折。","若问得人怜处，是轻颦时节。","主人特地出红妆，不要云心月。","三径虽然冷淡，有采莲舟楫。"]},{"t":"好事近 席上用景裴咏黄海棠韵","f":"词","c":["睡足淡梳妆，喜见诗人元白。","不学艳红妖紫，环花仙标格。","须知玉骨本天然，不是借人力。","准拟小春重看，望秋灰无射。"]},{"t":"好事近 为钱处和寿","f":"词","c":["缥酒颂青春，不减宜城桑落。","楼下玉人凝笑，散万英千萼。","绣衣当日帝王州，横飞看雕鹗。","闻道赐环书下，向金门持橐。"]},{"t":"好事近","f":"词","c":["小阁过重阳，愁对轻篁团色。","喜得蛮笺新唱，似夜光明月。","萸房菊蕊定相怜，酩酊误蕉叶。","犹记去年今夜，听歌声清切。"]},{"t":"好事近 东湖席上次曾守韵，时幕曹同集","f":"词","c":["风细晚轩凉，妙句初挥新墨。","绿水池中宾佐，对嫩荷擎绿。","坐看微月上云头，清臂映寒玉。","只恐朝来酒醒，有文书羁束。"]},{"t":"好事近","f":"词","c":["烂漫海棠花，多谢东君留得。","眉寿堂边风景，与蓬瀛咫尺。","桃红李白竞争妍，绿野尽春色。","只欠樱唇清唱，怕行云南北。"]},{"t":"好事近 别傅丈","f":"词","c":["柳岸碧漪深，底事催人行色。","无计曲留情话，只别愁如织。","小蛮樊素两倾城，几度醉狂客。","明日扁舟西去，听歌声不得。"]},{"t":"正宫导引","f":"词","c":["重华天子，长至奉神虞。","九奏会轩朱。","星晖云润东方晓，拜贶竹宫初。","归来千乘护皇舆。","瑞景集金铺。","鸡竿高唱恩书下，惠露匝中区。"]},{"t":"江城子 赠举之","f":"词","c":["冥冥云屿两经秋。","落霞收。","断烟留。","小阁凉生，清馥凝金虬。","乘兴开颜那草草，烦玉腕，举琼舟。","明年此日楚江头。","极层楼。","望丹丘。","只恐溪山，千里碍凝眸。","重倚阑干相忆处，寻过雁，作书邮。"]},{"t":"江城子 其一 饯黄魁","f":"词","c":["当年提笔上词坛。","琢琅玕。","涌波澜。","晁董声名，一日满人间。","底事远烦骐骥足，梅岭外，砚台边。","元戎倾盖有馀欢。","酒杯宽。","语离难。","只恐江边，明日起青翰。","暂去平分风与月，迎细札，步金銮。"]},{"t":"江城子 其二 黄宪生日代作","f":"词","c":["江如罗带抱山青。","好风轻。","五云横。","北斗南边，烨烨使华星。","两路平反多少事，培吉德，赍长生。","当年乌府振冠缨。","稔英声。","起鹏程。","垂上丹霄，回首志澄清。","雪片深深梅著子，归路近，看和羹。"]},{"t":"西江月 其二 再作","f":"词","c":["席上酒杯难减，鼎中药味频加。","老人争得脸如霞。","镜里衰容人怕。","檐溜尽成冰柱，前村变却梅花。","琼瑶破碎为行车。","冻雀盈枝堪画。"]},{"t":"西江月 其一 雪中","f":"词","c":["小室坐毡重叠，红炉兽炭交加。","一卮村酒吸流霞。","窗外寒威可怕。","心在盘洲种柳，眼看密雪飞花。","银杯缟带不随车。","江上渔蓑难画。"]},{"t":"阮郎归","f":"词","c":["澄清阁下藕如船。","扁舟曾采莲。","向来辛苦叠青钱。","而今知几年。","人去也，客凄然。","酒泉添泪泉。","一杯今夜且留连。","断肠芳草边。"]},{"t":"奉禋歌","f":"词","c":["吹葭缇籥气潜分。","云采宜书壤效珍。","长日至，一阳新。","四时玉烛和匀。","物欣欣。","造化转洪钧。","郊之祭，孤竹管，六变舞云门。","自古严禋。","牺牲具，粢盛洁，豆笾陈。","衮龙陟降，币玉纷纶。","彻高阍。","灵之斿，神哉沛，排历昆仑。","九歌毕，盈郊瞻槱燎，斗转参横将旦，天开地辟如春。","清跸移轮。","阗然鼓吹相闻。","籋祥云。","欢胪八陛，厘逆三神。","圣矣吾君。","华封祝、慈宫万寿，椒掖多男，六合同文。"]},{"t":"降仙台","f":"词","c":["漏残柝静鸡声远，到高燎。","入层霄。","云裘蟠瑞霭，天步下嘉坛，旗旆飘摇。","黄麾列仗貔貅整，气压江潮。","导前从后盛官僚。","玉佩间金貂。","望扶桑，日渐高。","阴霾霜雪，底处不潜消。","辇路祥飙。","披拂绛纱袍。","云间瑞阙仰岧峣。","播春泽、喜浃黎苗。","礼成大庆，鳌三抃、受昕朝。"]},{"t":"临江仙 其六 寿周材","f":"词","c":["瓜瓞绵绵储庆远，闲平代有名人。","一襦五裤说朱轮。","云逵鸳缀近，雷社虎符新。","正是泗滨浮磬日，潘舆一粲欣欣。","鸾歌飞起杏梁尘。","巢莲龟问岁，介寿酒融春。"]},{"t":"临江仙 盘洲饯汉章","f":"词","c":["两载绣衣频驻节，金莲曾印青苔。","匆匆归去寿琼杯。","曲终挥别泪，江上片帆开。","记得秋宵山吐月，酒酣同上层台。","杖藜何日解重来。","相思凭过雁，飞送一枝梅。"]},{"t":"临江仙 其三 稚川生日","f":"词","c":["钓濑怀珠山韫玉，谪仙至自蓬莱。","它年勋业上云台。","棣华开幕府，莲沼屈英才。","南极逢秋光烂烂，门阑香雾萦回。","须将寿卉荐琼杯。","篱东明日菊，借取一枝来。"]},{"t":"临江仙 其五 傅丈生日","f":"词","c":["干吕青云垂宝露，结邻恰挂初弦。","瑞光腾踊杂非烟。","骑箕瞻鼻祖，孕昴控胎仙。","勋业子卿全汉节，壮怀久寄林泉。","举觞低唱脸舒莲。","寿高人七十，果熟岁三千。"]},{"t":"临江仙 其二 会黄魁","f":"词","c":["北斗南头云送喜，人间快睹魁星。","向来平步到蓬瀛。","如何天上客，来佐海边城。","方伯娱宾香作穗，风随歌扇凉生。","且须滟滟引瑶觥。","十年迟凤诏，万里寄鹏程。"]},{"t":"临江仙 其七 送罗倅伟卿权新州","f":"词","c":["远驾星屏临百粤，康沂户户歌功。","使君五马去乘骢。","卖刀无旷土，赠扇有仁风。","莫唱渭城朝雨曲，片帆时暂西东。","促归行拜紫泥封。","九霄先步武，三接未央宫。"]},{"t":"临江仙 其一 郑盐生日","f":"词","c":["向日鹓行瞻凤彩，共期直上金銮。","却来持节海云边。","身兼三使者，名是一仙官。","汉室中兴高密冠，千年苗裔蝉联。","左弧嘉庆舞祥烟。","橘中招四老，同醉酒如泉。"]},{"t":"临江仙 其四","f":"词","c":["烟凑横岚霞抱日，望中衰草稠稠。","西风吹恨著扁舟。","马卿多病后，方寸不禁秋。","颇念银壶行绿醑，共听渔子清讴。","梦魂飞过海山楼。","人随秋易老，情寄水东流。"]},{"t":"南歌子 其一 雪中和景裴韵","f":"词","c":["闰岁饶光景，中旬始打春。","拥炉看雪酒催人。","梁上不曾飞落、去年尘。","未暇巾车出，何妨举盏频。","斜川日月已成陈。","想得前村仙子、晚妆匀。"]},{"t":"南歌子 其四 喜晴用前韵","f":"词","c":["住得如筛雪，方欣有脚春。","谁云三尺不须循。","若是诗僧月下、许敲门。","钜竹多中断，残梅竞小颦。","畦丁说与主林神。","扫洒板桥前径、待吾人。"]},{"t":"南歌子 其二 呈叶宪","f":"词","c":["多病都缘老，寒阴可惜春。","栽桃种竹怕因循。","移转篮舆藤杖、未开门。","真率须如约，安排欲效颦。","莫将筝笛损精神。","自有啼莺舞鹤、解随人。"]},{"t":"南歌子 其五 示裴弟","f":"词","c":["强作千年调，难逾五度春。","脊令继踵漫相循。","休要关心药裹、也扃门。","蕙帐银杯化，纱窗翠黛颦。","烧香试问紫姑神。","一岁四并三乐、几多人。"]},{"t":"南歌子 童岭作","f":"词","c":["云拂山腰过，风吹雨点来。","田园好处有池台。","记著相逢时节、海棠开。","蝴蝶那无梦，鸳鸯亦有媒。","藏钩解佩两三杯。","明日水边沙际、首空回。"]},{"t":"南歌子 其六 寄景卢","f":"词","c":["南浦山罗列，东湖水渺弥。","主人好客过当时。","斗转参横时候、醉如泥。","莫管莺声老，从它柳絮飞。","野园春色别无奇。","船上有花多酒、未须归。"]},{"t":"南歌子 其三 示景裴弟，时叶宪明日真率","f":"词","c":["顽健输村老，嬉游付后生。","七旬才有五清明。","须趁良辰美景、绕园行。","云意将飞雪，天心未肯晴。","难将性命作人情。","只合拥炉清坐、阅医经。"]},{"t":"思佳客 次韵蔡文同集钱漕池亭","f":"词","c":["花信今无一半风。","芙蓉出水几时红。","看成弱柳阴阴绿，自在迁莺巧语中。","风傍户，月留空。","金尊相对醉珠栊。","归鞭欲指江南去，回首霞标忆旧峰。"]},{"t":"点绛唇 别帅宪","f":"词","c":["天末相逢，醉中不讶车茵污。","一声鸣橹。","惊散眠沙鹭。","我是行人，却送行人去。","听金缕。","莫辞甘醑。","别泪飞寒雨。"]},{"t":"选冠子","f":"词","c":["雨脚报晴，云容呈瑞，夜雪萦盈连昼。","千岩曳缟，万瓦堆琼，稍稍冷侵怀袖。","鹤氅神仙，兔园宾客，高会坐移清漏。","想灞陵桥畔，苦吟缓辔，耸肩寒瘦。","向此际、色映堂阴，香传梅影，寒力更欺尊酒。","左符词伯，蛮笺巧思，不道起风飞柳。","舞态弓弯，一声低唱，蛾笑绿分烟岫。","任杯行潋滟，为公沈醉，莫教停手。"]},{"t":"浣溪沙","f":"七言古诗","c":["邦伯今推第一流。","几因歌席负诗筹。","一时文采说台州。","雨脚渐收风入牖，云心初破月窥楼。","翠眉相映晚山秋。"]},{"t":"浣溪沙 其二 以鸳鸯梅送曾守，是日，曾守携家游南园","f":"七言古诗","c":["报道倾城出洞房。","水边疏影弄清香。","风流更有小鸳鸯。","蝉鬓半含花下笑，蛾眉相映醉时妆。","梦魂不到白云乡。"]},{"t":"浣溪沙 席上别王巨济。先是，两姬免冠，王夺两秩，继以章罢","f":"七言古诗","c":["丹桂飘香已四番。","杖藜携手自今难。","黯然离恨满江干。","壁上两冠元是谶，花前双韵几时弹。","中秋后夜与谁看。"]},{"t":"浣溪沙 寿方稚川","f":"七言古诗","c":["占得登高一日先。","跨云来作地行仙。","天将黄菊助长年。","健笔已凌枚叟赋，高怀欲著祖生鞭。","骎骎彯组向甘泉。"]},{"t":"浣溪沙 其三 以鸳鸯梅送钱漕","f":"七言古诗","c":["玉颊微醺怯晚寒。","可怜凝笑整双翰。","枝头一点为谁酸。","只恐轻飞烟树里，好教斜插鬓云边。","淡妆仍向醉中看。"]},{"t":"浣溪沙 其一 景卢以米书眉间一点黄之曲饯送郑宪，因用其韵","f":"七言古诗","c":["举目霜林叶叶黄。","使星归骑未须忙。","烟鬟千叠弄残妆。","内殿恩光承雨露，外台风力挟冰霜。","应怀三径杂花香。"]},{"t":"浣溪沙 其一 饯范子芬行","f":"七言古诗","c":["整顿春衫欲跨鞍。","一杯相属少开颜。","愁眉不似旧时弯。","未见两星添柳宿，忍教三叠唱阳关。","相思空望会稽山。"]},{"t":"浣溪沙 其四 席中答钱漕","f":"七言古诗","c":["忆得熙春晓立班。","使星曾入紫微垣。","归来小饮友芝兰。","投辖风流今复见，开尊礼数自来宽。","更看宝唾写乌阑。"]},{"t":"浣溪沙 其二 席上再作","f":"七言古诗","c":["不见丹丘三十年。","青山碧水想依然。","自惊绿鬓已苍颜。","月在柳梢曾径醉，雨荒院菊有谁怜。","绣衣归与古人言。"]},{"t":"番禺调笑 其九 沉香浦","f":"词","c":["深浦。","停舟处。","只恐越装相染污。","奇香一见如泥土。","投著水中归去。","令公早晚回朝著。","无物迟留鸣橹。"]},{"t":"番禺调笑 其三 海山楼","f":"词","c":["奇货。","归帆过。","击鼓吹箫相应和。","楼前高浪风掀簸。","渔唱一声山左。","胡床邀月轻云破。","玉麈飞谈惊座。"]},{"t":"番禺调笑 其八 贪泉","f":"词","c":["饮器。","贪泉水。","山乳涓涓甘似醴。","怀金嗜宝随人意。","枉受恶名难洗。","真清方伯端无比。","未使吴君专美。"]},{"t":"番禺调笑 其五 朝汉台","f":"词","c":["音乐。","传佳作。","盖海旌幢开观阁。","绮霞飞渡青油幕。","好是登临行乐。","当时朝汉心倾藿。","望断长安城郭。"]},{"t":"渔家傲 其一 破子","f":"词","c":["渔父饮时花作荫。","羹鱼煮蟹无它品。","世代太平除酒禁。","渔父饮。","绿蓑藉地胜如锦。","渔父醉时收钓饵。","鱼梁晒翅闲乌鬼。","白浪撼船眠不起。","渔父醉。","滩声无尽清双耳。"]},{"t":"番禺调笑 其四 素馨巷","f":"词","c":["名世。","花无二。","高压阇提倾末利。","素丝缕缕联芳蕊。","一片云生宝髻。","屑沈碎麝香肌细。","剩馥熏成心字。"]},{"t":"减字木兰花 太守移具饯行县偶作","f":"词","c":["使君情素。","念我明朝行县去。","一醉相留。","和气欢声到小楼。","暂时南北。","莫唱渭城朝雨曲。","此去农郊。","收拾童儿五裤谣。"]},{"t":"减字木兰花 曾谹父落成小阁，次其韵","f":"词","c":["藩车容裔。","挺挺风流追两地。","粲斗分星。","诗句当年汗简青。","疏帘披绣。","共看横云晴出岫。","新月如钩。","来照琼彝醉小楼。"]},{"t":"望江南 其一 答徐守韵","f":"词","c":["嗟故岁，夏旱复秋阳。","十雨五风皆定数，千方百计为灾伤。","小郡怎禁当。","劳拊字，惠露洽丁黄。","田舍炊烟常蔽野，居民安堵不离乡。","祖道免赍粮。"]},{"t":"望江南/忆江南 其二 再作","f":"词","c":["倾盖侣，古语诵邹阳。","曲水一觞今意懒，阳关三叠重情伤。","离恨落花当。","人截镫，归骑莫仓黄。","谁肯甘心迷簿领，不如袖手傲家乡。","高枕熟黄粱。"]},{"t":"望海潮 题双岩堂","f":"词","c":["重溟倒影，五芝含笑，神仙今古台州。","山拥黄堂，烟披画戟，双岩瑞气长浮。","前事记鳌头。","有百年台榭，千室嬉游。","墨宝凄凉，风凌雨蠹尽悠悠。","规恢共仰贤侯。","当政成五月，景对三秋。","飞栋干云，虚檐受露，放怀不减南楼。","宾燕奉觥筹。","妙绮笺琼藻，声度歌喉。","只恐棠阴成后，趣去侍凝旒。"]},{"t":"清平乐 以千叶粉红牡丹送曾守","f":"词","c":["轻红淡白。","蓬阆神仙谪。","魏紫姚黄夸异色。","到得海边初识。","玉阑不语如颦。","虚教春尽三分。","却问檀心谁向，多情更属东君。"]},{"t":"清平乐 次曾守韵","f":"词","c":["风鬟飞乱。","寒入秦筝雁。","情似云阴浑未展。","雨脚更飘银线。","横枝有意先开。","玉尘欲伴金罍。","何日舞裀歌扇，后堂重到惟梅。"]},{"t":"渔家傲引/渔家傲 其十二","f":"词","c":["腊月行舟冰凿罅。","潜鳞透暖偏堪射。","岁岁年年篷作舍。","三冬夜。","牛衣自暖何须借。","滕六晚来方命驾。","千山绝影飞禽怕。","江上雪如花片下。","宜入画。","一蓑披著归来也。"]},{"t":"渔家傲引/渔家傲 其十一","f":"词","c":["子月水寒风又烈。","巨鱼漏网成虚设。","圉圉从它归丙穴。","谋自拙。","空归不管旁人说。","昨夜醉眠西浦月。","今宵独钓南溪雪。","妻子一船衣百结。","长欢悦。","不知人世多离别。"]},{"t":"渔家傲引/渔家傲 其六","f":"词","c":["六月长江无暑气。","怒涛漱壑侵沙觜。","飐飐轻舟随浪起。","何不畏。","从来惯作风波计。","别溆藕花舒锦绮。","采莲三五谁家子。","问我买鱼相调戏。","飘芰制。","笑声咭咭花香里。"]},{"t":"渔家傲引/渔家傲 其一","f":"词","c":["十月橘洲长鼓枻。","潇湘一片尘缨洗。","斩得钓竿斑染泪。","中夜里。","时闻鼓瑟湘妃至。","白发垂纶孙又子。","得钱沽酒长长醉。","小艇短篷真活计。","家云水。","更无王役并田税。"]},{"t":"渔家傲引/渔家傲 其七","f":"词","c":["七月凛秋飞叶响。","长吟杳杳澄江上。","秃尾槎头添一网。","丝自纺。","新炊菰饭更相饷。","渡口青烟藏叠嶂。","岸旁红蓼翻轻浪。","鸂鶒沈浮双漾漾。","闻鸣桨。","高飞拍拍穿林莽。"]},{"t":"渔家傲引/渔家傲 其九","f":"词","c":["九月芦香霜旦旦。","丹枫落尽吴江岸。","长濑黄昏张蟹断。","灯火乱。","圆沙惊起行行雁。","半夜系船桥北岸。","三杯睡著无人唤。","睡觉只疑桥不见。","风已变。","缆绳吹断船头转。"]},{"t":"渔家傲引/渔家傲 其四","f":"词","c":["四月圆荷钱学铸。","鳞鳞波暖鸳鸯语。","无数燕雏来又去。","鱼未取。","钓丝直上蜻蜓聚。","风弄碧漪摇岛屿。","奇云蘸影千峰舞。","骑马官人江上驻。","天且暮。","借舟送过沧波渡。"]},{"t":"渔家傲引/渔家傲 其三","f":"词","c":["三月愁霖多急雨。","桃江绿浪迷洲渚。","西塞山边飞白鹭。","烟横素。","一声欸乃山深处。","红雨缤纷因水去。","行行寻得神仙侣。","楼阁五云心不住。","分凤侣。","重来翻恨花相误。"]},{"t":"渔家傲引/渔家傲 其五","f":"词","c":["五月河中菱荇遍。","丝纶欲下相萦绊。","却掉船来芳草岸。","呼侣伴。","蓑衣不把金章换。","碧落云高星烂烂。","波心举网星光乱。","跃出鲤鱼长尺半。","回首看。","孤灯一点风吹散。"]},{"t":"渔家傲引/渔家傲 其一","f":"词","c":["正月东风初解冻。","渔人撒网波纹动。","不识雕梁并绮栋。","扁舟重。","眠鸥浴雁相迎送。","溪北画桥弯螮蝀。","溪南古岸添青葑。","长把鱼钱寻酒瓮。","春一梦。","起来拈笛成三弄。"]},{"t":"渔家傲引/渔家傲 其八","f":"词","c":["八月紫莼浮绿水。","细鳞巨口鲈鱼美。","画舫问渔篙暂舣。","欣然喜。","金齑顷刻尝珍味。","涌雾驱云天似洗。","静看星斗迎蟾桂。","枕棹眠蓑清不睡。","无名利。","谁人分得逍遥意。"]},{"t":"渔家傲引/渔家傲 其二","f":"词","c":["二月垂杨花糁地。","荻芽迸绿春无际。","细雨斜风浑不避。","青笠底。","三三两两鸣桹起。","新妇矶边云接袂。","女儿浦口山堆髻。","一拥河豚千百尾。","摇食指。","城中虚却鱼虾市。"]},{"t":"眼儿媚","f":"词","c":["瀛仙好客过当时。","锦幌出蛾眉。","体轻飞燕，歌欺樊素，压尽芳菲。","花前一盼嫣然媚，滟滟举金卮。","断肠狂客，只愁径醉，银漏催归。"]},{"t":"眼儿媚","f":"词","c":["黄堂风转碧幢开。","笙鹤九天来。","三冬爱日，一方惠露，人在春台。","持杯多赞松乔喜，低唱列金钗。","明年此日，紫微垣里，光应中台。"]},{"t":"朝中措 其三 邓盐生日","f":"词","c":["青云垂下不争程。","绣斧记澄清。","黄木湾头人闹，耳边都是欢声。","仙家咫尺，波涵渤澥，路挹蓬瀛。","十日东君不老，一星南极长明。"]},{"t":"朝中措 其四 帅生日","f":"词","c":["斗南楼阁舞祥云。","为寿几多人。","有酒恰如东海，年年为满金尊。","无双治行，儿童咏德，草木沾仁。","只把空虚三院，亦须笑傲千春。"]},{"t":"朝中措 其一 曾守生辰","f":"词","c":["当年召父治南阳。","千室颂慈祥。","今代天台太守，声名已达岩廊。","风流闲暇，胡床乘兴，燕寝凝香。","好去花砖视草，珠庭喜见微黄。"]},{"t":"朝中措 其二","f":"词","c":["江西文派有新图。","诗律嗣东湖。","十首齐安书事，君王曾问相如。","牙签翻架，银钩落纸，美玉明珠。","见说诏岁金匮，后来天下浑无。"]},{"t":"朝中措 其六 黄帅宪侍儿倩奴","f":"词","c":["嘉禾一别十经春。","清泖记垂纶。","今日天涯沦落，跫然一见佳人。","酒浮重碧，声低云叶，香趁霞裙。","准拟魁星归去，它时相会金门。"]},{"t":"朝中措 其五 苏少莲母生日","f":"词","c":["西昆当日下云骈。","采藻奉苏仙。","玉节荣看棠棣，斑衣笑俯芝兰。","寿觞争举，歌萦蛾绿，香袅龙涎。","须与寄声鸾鹤，飞来岁岁年年。"]},{"t":"满江红 其四 黄堂席上答太守","f":"词","c":["燕寝香凝，官事了、诗情充溢。","归后院、花容争媚，柳眉添碧。","老子胡床常自叹，轻裾长袖从何觅。","探城楼、此际夜如何，更筹一。","人已老，春将毕。","临曲水，才旬日。","快朝来雨过，鱼儿争出。","淡酒一杯空酩酊，黄堂千骑真安逸。","问朱轓、何日到丘园，联綦迹。"]},{"t":"满江红","f":"词","c":["春色匆匆，三分过、二分光景。","吾老矣，坡轮西下，可堪弄影。","曲水流觞时节好，茂林修竹池台永。","望前村、绿柳荫茅檐，云封岭。","蜂蝶闹，烟花整。","百年梦，如俄顷。","这回头陈迹，漫劳深省。","吹竹弹丝谁不爱，焚琴煮鹤人何肯。","尽三觥、歌罢酒来时，风吹醒。"]},{"t":"满江红 其五 席上答叶宪","f":"词","c":["百计留春，春不住、愁怀填溢。","争如对、宝梳压鬓，翠环铺碧。","紫绶金章都是梦，云庐花坞如何觅。","劝金杯、浅笑傍宾筵，须均一。","前夜月，新离毕。","收歰雨，呈红日。","荷主人情厚，五云齐出。","一颗樱桃天付与，数声水调人飘逸。","叹荒园、三月百花残，无踪迹。"]},{"t":"满江红 其三 答景卢","f":"词","c":["衰老贪春，春又老、尊罍交溢。","凝目处、清漪拍岸，四山堆碧。","白也论文情最厚，维摩示病心难觅。","到盘洲、车骑太匆匆，觞浮一。","春再见，官期毕。","归路近，长安日。","奉清时明诏，迭回更出。","上殿风霜生颊齿，元龟献替图无逸。","记而今、杖策过溪桥，留行迹。"]},{"t":"满江红 其二 郑宪席上再赋","f":"词","c":["累月愁霖，知今夕、是何天色。","秋老矣、芙蓉遮道，黄花留客。","长有霜螯来左右，谁言枥马能煎迫。","眄高穹、重叠起顽云，星难摘。","罗绮盛，轩窗窄。","心已醉，肩须拍。","更十分行酒，再三相吓。","凤诏十行归路近，桂华千里明年隔。","趁闲时、楼上共凝眸，芦花白。"]},{"t":"满江红 其二 和徐守三月十六日","f":"词","c":["雨过春深，溪水涨、绿波溶溢。","年年是、杨花吹絮，草茵凝碧。","驹隙光阴身易老，槐安梦幻醒难觅。","算六分、春色五分休，才留一。","雁鹜静，文书毕。","尘外趣，壶中日。","喜兰亭修禊，郊坰忺出。","合璧连珠同啸咏，怒猊渴骥尤清逸。","酒酣时、梁上暗尘飞，无痕迹。"]},{"t":"满江红","f":"词","c":["暮雨萧萧，飞败叶、增添秋色。","登高会、痴风吹散，山居嘉客。","人世难逢开口笑，老来更觉流年迫。","到如今、黄菊满园开，无人摘。","珠履凑，铢衣窄。","萦翠袖，催牙拍。","索松儿添半，战酣相吓。","橘绿橙黄时节好，舞停歌罢门墙隔。","酒醒时、枕上一声鸡，东方白。"]},{"t":"满庭芳 其三 和叶宪韵","f":"词","c":["柳径花台，熙熙春动，游人珥堕簪遗。","枯藤到处，绿刺惹冠衣。","雪后园林更好，琼作佩、香满横枝。","巡檐久，留连一笑，不管午阴移。","盘洲，今雅集，皇华飞盖，挥麈迟迟。","觉龟鱼增价，草木生辉。","梁上不教尘落，谈文字、酒散星稀。","明年好，玉津随驾，回首记襟期。"]},{"t":"满庭芳 辛丑春日作","f":"词","c":["华发苍头，年年更变，白雪轻犯双眉。","六旬过四，七十古来稀。","问柳寻花兴懒，拈筇杖、闲绕园池。","尊中有，青州从事，无意唤琼彝。","人生，何处乐，楼台院落，吹竹弹丝。","奈壮怀销铄，病费医治。","漫道琴弦绿绮，游鱼听、山水谁知。","盘洲怨，盟鸥闲阔，瘗鹤立新碑。"]},{"t":"满庭芳 其九 景卢有南昌之行，用韵惜别，兼简司马汉章","f":"词","c":["雨洗花林，春回柳岸，窗间列岫横眉。","老来光景，生怕聚谈稀。","何事扁舟西去，收杖屦、契阔鱼池。","流觞近，诗筒暂歇，焉用虎文彝。","良辰，怀旧事，海棠花下，笑摘垂丝。","叹五年一别，万病难治。","几处绣衣尘迹，歌舞地、乌鹊曾知。","君今去，珠帘暮卷，山雨拂崇碑。"]},{"t":"满庭芳 其一 再作寄景卢","f":"词","c":["旧日盘洲，藏钩卜夜，松儿笑拣双眉。","老人好静，此乐数年稀。","尚记乘舟西溯，楼卷雪、曾到雷池。","今非昔，畏寒闭户，弃掷夏商彝。","入春，逾两月，轻烟非雾，细雨如丝。","任风颓花架，不惮装治。","想得醉吟滕阁，家园事、争解详知。","归来好，猿惊鹤怨，孤负辋川碑。"]},{"t":"满庭芳 其七 酬赵宪","f":"词","c":["当国无功，归田有分，四山浓抹烟眉。","春云多变，清昼惠风稀。","欲踵兰亭故事，溪水涨、簪盍鹅池。","临修竹，一觞一咏，考古到辛彝。","当时。","龙衮侧，亲闻胪句，天语如丝。","谩三年博士，局冗争治。","底事绣衣留滞，青天瑞、奴隶皆知。","迎归诏，鸾台凤阁，名记壁间碑。"]},{"t":"满庭芳 其六 酬赵泉","f":"词","c":["春入花畦，雪迷筠坞，柳梢未肯低眉。","泥深路滑，车马往来稀。","平地琼琚盈尺，冰冻解、檐水如池。","皇华喜，增添泉货，不铸尚方彝。","光阴，驹过隙，髭髯如戟，容易成丝。","把诗盟长讲，酒病休治。","两两垂螺舞彻，藏羌管、人已潜知。","樯乌转，钱流地上，褒诏便刊碑。"]},{"t":"满庭芳 代上陈帅生日","f":"词","c":["昴宿光芒，德星家世，当时飞舞华旗。","风清玉宇，珠露缀瑶枝。","八桂苍苍耸壑，问椿木、同数秋期。","黄堂上，油幢转影，美酒注金卮。","英躔，名誉早，青箱传学，黄绢摛辞。","说江东治行，召杜肩齐。","畏爱双行五管，收绣斧、却把旌麾。","欢声沸，明年此日，公在凤凰池。"]},{"t":"满庭芳 其八 再作","f":"词","c":["草阁烟横，花蹊雨润，伤春谁画鸦眉。","药囊未减，尊酒自然稀。","堪叹云和挂壁，弦半绝、鼠啮龙池。","投壶罢，凭阑玩古，罗列父丁彝。","龟巢，添绿皱，残梅片片，新柳丝丝。","恨风狂折竹，鹤病谁治。","自信年衰景短，甘冷淡、应也天知。","埙篪奏，清歌醉墨，一一上圭碑。"]},{"t":"满庭芳 其五 答景卢遣怀","f":"词","c":["蝴蝶梦魂，芭蕉身世，几人得到庞眉。","十分如意，天赋古今稀。","昼日猥叨三接，摩鹏翼、曾化鲲池。","槐阴下，深惭房魏，那敢作封彝。","雁行，争接翅，北门炬烛，西掖纶丝。","幸归来半世，园路先治。","渔唱樵歌不到，莺燕语、何畏人知。","编花史，修篁千亩，封植具穹碑。"]},{"t":"满庭芳 其一 酬徐守","f":"词","c":["风搅花间，雨悭柳下，人人懒拂愁眉。","年荒省事，投辖井中稀。","架上舞衣尘积，弦索断、筝雁差池。","南柯梦，转头陈迹，饥鼠穴空彝。","新年，官事少，秋蛇春蚓，重叠乌丝。","更出奇花判，百病都治。","报道行厨办也，乌鹊喜、龟鹤前知。","更书近，鹓行浸远，长对去思碑。"]},{"t":"满庭芳 其四 再赠叶宪","f":"词","c":["同病相怜，冻吟谁伴，漫怀举案齐眉。","槐安梦境，一笑自来稀。","未到斜川见雪，春欲半、尚压铜池。","今思古，拊盆击筑，虿鼎闲夔彝。","何时。","天意解，并游花坞，旋扫蛛丝。","对壶中闲日，冗牍休治。","四坐同盟情话，飞玉麈、万事多知。","杯盘省，浅斟随意，真率视前碑。"]},{"t":"满庭芳 其二 酬叶宪","f":"词","c":["殢酒销愁，逢场作戏，何曾择地伸眉。","诗筒来往，如我与君稀。","喜得青春有闰，添日月、款曲临池。","洲盘有，山肴野蔌，安用设鸡彝。","老来，空自笑，一头梳雪，两鬓吹丝。","便常逢社饮，聋不堪治。","曾就新年真率，花神报、蜂蝶皆知。","东风恶，江梅欲尽，荐福莫轰碑。"]},{"t":"虞美人","f":"词","c":["芭蕉滴滴窗前雨。","望断江南路。","乱云重叠几多山。","不似倦飞鸥鹭、便知还。","角声更听谯门弄。","夜夜思归梦。","鄱江楼下水含漪。","孤负钓滩烟艇、绿蓑衣。"]},{"t":"蝶恋花","f":"词","c":["漠漠水田飞白鹭。","夏木阴阴，巧啭黄鹂语。","金匮诗人新得句。","江山应道来何暮。","好向金门联步武。","何事双旌，却为丹丘驻。","琼斝十分须一举。","看看紫诏催归去。"]},{"t":"鹧鸪天 次李举之见寄韵","f":"词","c":["报答风光思更新。","安排好语续阳春。","罗胸玉藻英华别，信手银钩点画匀。","歌妙曲，想光尘。","相望尺五叹参辰。","曲终强对红颜笑，欠我高谈惊座人。"]},{"t":"鹧鸪天 其二 十九孙入学，因作小集。景裴有作，次其韵","f":"词","c":["两塾弦歌日日春。","不容坐席更凝尘。","常思芳桂攀燕窦，未见童乌继子云。","流庆泽，仰家尊。","救荒阴德过于门。","从师已是平原客，毛遂怀绷作弄孙。"]},{"t":"鹧鸪天 胡提舶生日","f":"词","c":["月上初弦映左弧。","葭吹六琯转璇枢。","日边远近瞻新渥，天下中庸系两都。","犀献角，蚌回珠。","皇皇星节烛扶胥。","满斟北海尊中酒，请寿安期涧底蒲。"]},{"t":"鹧鸪天 次曾守游梅园韵","f":"词","c":["领客携尊花底开。","薄寒初送雨声来。","一声未弄林间笛，几片低飞阁下梅。","酬的皪，少迟回。","不妨春雪撒银杯。","玉肌莫放清香散，更待晴时赏一回。"]},{"t":"鹧鸪天 其一 席上赏牡丹用景裴韵","f":"词","c":["莫问甘醪浊与清。","试将一酌破愁城。","海棠过后荼蘼发，堪叹人间不再生。","心已老，眼重明。","嫣然国色带朝酲。","耳边听得兰亭曲，一咏流觞已有名。"]},{"t":"渔家傲 其二","f":"词","c":["渔父醒时清夜永。","澄澜过尽征鸿影。","略略风来敧舴艋。","渔父醒。","月高露下衣裳冷。","渔父笑时莺未老。","提鱼入市归来早。","一叶浮家生计了。","渔父笑。","笑中起舞渔家傲。"]},{"t":"赋孤雁","f":"七言律诗","c":["云飞水宿过炎凉，回想来时道路长。","夜月照惊唯吊影，朔风吹断不成行。","人间无处逃矰缴，岁晚何曾饱稻粱。","傥以能鸣免烹杀，系书犹可到衡阳。"]},{"t":"送刘元忠学士还南京","f":"七言古诗","c":["昔见相公登瀛洲，今见公子为校雠。","鲲鹏变化三十载，我生安得不白头。","君前拜恩父前庆，暂向南都秉顺流。","南都留守颇为喜，将吏入贺靴声遒。","酒舁银瓮羊脔炙，上下和煦移凉秋。","归来却上柳堤路，西风健马控花虬。"]},{"t":"番禺调笑 其一 羊仙","f":"词","c":["南土。","贤铜虎。","黄木湾头腾好语。","骑羊执穗神仙五。","拭目摩肩争睹。","无双治行今犹古。","嘉瑞流传乐府。"]},{"t":"番禺调笑 其二 药洲","f":"词","c":["寒食。","人如织。","藉草临流罗饮席。","阳春有脚森双戟。","和气欢声洋溢。","洲边药灶成陈迹。","九曜摩挲奇石。"]},{"t":"番禺调笑 其七 蒲涧","f":"词","c":["佳节。","初春月。","飞盖倾城尊俎列。","安期驾鹤朝金阙。","丹灶分留岩穴。","山中花笑秦皇拙。","祠殿荒凉虚设。"]},{"t":"番禺调笑 其十一 破子","f":"词","c":["南海。","繁华最。","城郭山川雄岭外。","遗踪嘉话垂千载。","竹帛班班俱在。","元戎好古新声改。","调笑花前分队。","高会。","尊罍对。","笑眼茸茸回盼睐。","蹋筵低唱眉弯黛。","翔凤惊鸾多态。","清风不用一钱买。","醉客何妨倒载。"]},{"t":"句降黄龙舞 其一","f":"词","c":["伏以玳席接欢，杯滟东西之玉；","锦茵唤舞，钗横十二之金。","咸驻目于垂螺，将应声而曳茧。","岂无本事，愿吐妍辞。"]},{"t":"句降黄龙舞 其二 答","f":"词","c":["眄流席上，发水调于歌唇；","色授裾边，属河东之才子。","未满飞鹣之愿，已成别鹄之悲。","折荷柄而愁缕无穷，剪鲛绡而泪珠难贯。","因成绝唱，少相清欢。"]},{"t":"句降黄龙舞 其三 遣","f":"词","c":["情随杯酒滴郎心。","不忍重开翡翠衾。","封却软绡看锦水，水痕不似泪痕深。","歌罢舞停，相将好去。"]},{"t":"句南吕薄媚舞 其一","f":"词","c":["羽觞棋布，洽主礼于良辰；","翠袖弓弯，奏女妖之妍唱。","游丝可倩，本事愿闻。"]},{"t":"句南吕薄媚舞 其二 答","f":"词","c":["踏软尘之陌，倾一见于月肤；","会采蘋之洲，迷千娇于雨梦。","且蛾眉有伐性之戒，而狐媚无伤人之心。","既吐艳于幽闺，能齐芳于节妇。","果六尺之躯不庇其伉俪，非三寸之舌可脱于艰难。","尚播遗声，得尘高会。"]},{"t":"句南吕薄媚舞 其三 遣","f":"词","c":["兽质人心冰雪肤。","名齐节妇古来无。","纤罗不蜕西州路，争得人知是艳狐。","歌舞既阑，相将好去。"]},{"t":"盘洲杂韵上 含笑","f":"五言绝句","c":["自有嫣然态，风前欲笑人。","涓涓朝泣露，盎盎夜生春。"]},{"t":"拟古十三首 其一 行行重行行","f":"五言古诗","c":["行行重行行，南北各倦游。","昔人重别离，一日嗟三秋。","如何三秋暮，相见尚悠悠。","方寸正纡轸，何以写我忧。","仰瞻衡汉移，俯对兰菊遂。","臭味虽云同，光尘若为异。","回风凄且发，飘我别时袂。","欲知长相思，披衣不胜体。"]},{"t":"拟古十三首 其二 青青河畔草","f":"五言古诗","c":["青青河畔草，英英篱边菊。","雅雅当窗女，濯濯手如玉。","渊渊锦中意，粲粲未盈幅。","藁砧天一涯，刀头误行卜。","却鉴怨新眉，谁教远山绿。"]},{"t":"拟古十三首 其三 青青陵上柏","f":"五言古诗","c":["青青陵上柏，橚橚庭中竹。","人寿能几何，譬彼电过目。","一觞命昵交，且以慰心曲。","驾言长安游，川光晨可掬。","神州何赫戏，高城矗延属。","峣榭干星斗，彫栭错珠玉。","鳞鳞王公第，华缨夹绣毂。","放怀恣槃虞，端忧竟谁逐。"]},{"t":"拟古十三首 其四 今日良宴会","f":"五言古诗","c":["今日良宴会，朋簪故人家。","摇情绿绮琴，度曲渔阳挝。","放歌掀醉髯，晤语粲春葩。","列坐各知心，游扬相齿牙。","芬芳须及时，东扶忽西斜。","胡不厉逸翮，天津问仙槎。","无为甘寂漠，痼疾守烟霞。"]},{"t":"拟古十三首 其五 西北有高楼","f":"五言古诗","c":["西北有高楼，偃蹇轶千门。","绮栊纳飞月，璧珰碍翔云。","上有弦歌女，哀声启莺唇。","谁能为此曲，无乃返香人。","一章三致志，脩蛾有馀颦。","不惜饶清响，暗惊梁上尘。","所悲听者心，中无泾渭分。","愿作南冥鸟，夕饮玉池津。"]},{"t":"拟古十三首 其六 涉江采芙蓉","f":"五言律诗","c":["涉江采芙蓉，芳蕤荫幽沚。","相思不相见，芬香欲谁遗。","秋容感人心，浪浪睫涵泪。","不如膝上琴，哀音入君耳。"]},{"t":"拟古十三首 其七 明月皎夜光","f":"五言古诗","c":["明月皎夜光，瑟瑟扇商籁。","衡纪直西躔，云章斜左界。","感彼林薄凋，岁律倏云迈。","蜻蛚谁汝怜，悽悽鸣户外。","昔我耐久朋，著鞭道方泰。","尉藉缯缟轻，金兰旧盟改。","东井不及泉，须女无俦配。","君看贡公綦，白头愧倾盖。"]},{"t":"拟古十三首 其八 冉冉孤生竹","f":"五言古诗","c":["冉冉孤生竹，成阴幽谷中。","聿来君子室，葛藟施乔松。","乔松千百寻，攀附犹可穷。","思君江水深，褰裳难往从。","同心而偏栖，愧彼摩霄鸿。","灼灼芙蓉花，凌波媚芳风。","非不努力爱，秋至无归鸿。","昔盟傥不寒，谁叹久西东。"]},{"t":"拟古十三首 其九 庭前有奇树","f":"五言律诗","c":["庭前有奇树，黄鸟巢其枝。","之子不顾返，失此熙春期。","采采未盈掬，夕风已纷披。","路远怅莫致，虽多亦奚为。"]},{"t":"拟古十三首 其十 迢迢牵牛星","f":"五言古诗","c":["迢迢牵牛星，奕奕停梭女。","寻盟整瑶辔，缄情遵汉渚。","欣宴未斯须，别愁眉已度。","黄月不我留，残机忍重顾。","翻羡巫山云，朝朝楚王遇。"]},{"t":"拟古十三首 其十一 人生不满百","f":"五言古诗","c":["人生不满百，蟪蛄等春秋。","花月多风雨，何不蜡屐游。","朱光忽以驰，退舍未易留。","生前一杯乐，难与昧者谋。","临流羡芳沚，欢言泛轻舟。"]},{"t":"拟古十三首 其十二 孟冬寒气至","f":"五言古诗","c":["孟冬寒气至，冲风一何厉。","宿楚失故阴，思虫柱哀喙。","客来门冬冬，袖有尺书遗。","一读泪先零，再读心已醉。","妾如初开花，君如长流水。","花挽水回难，水捐花去易。","流水何时休，春荣难久恃。"]},{"t":"拟古十三首 其十三 明月何皎皎","f":"五言古诗","c":["明月何皎皎，舒光瑩窗绮。","宛转羞空床，披轩步庭际。","故爱同一心，新愁今两耳。","咫尺相会难，迢迢若千里。","况复千里隔，忧端无穷已。"]},{"t":"谢洪庆善提刑遗法帖","f":"七言古诗","c":["纷纷渴骥竞秋蛇，镌镵收拾俱名家。","吾宗尺牍擅天下，年来野鹜谁肩差。","庭前书带凝寒绿，架上牙签富新轴。","中藏墨妙更奇奇，长物不留沾剩馥。","生平小楷拘蝇头，岂知虿尾与银钩。","从今已办笔成冢，学奇还许登门不。"]},{"t":"春思","f":"五言律诗","c":["自闻郊外景，多病负年光。","沐雨桃容腻，耽春蝶兴狂。","幽期知我背，迟日为谁长。","一枕虚窗寂，炉烟续旧香。"]},{"t":"晚望","f":"五言律诗","c":["古堞高亭暮，登临远眺时。","菊房栖渥露，荷盖偃清漪。","遵渚归鸿集，投林啸狖悲。","关情聊绘句，独立自迟迟。"]},{"t":"欲雨","f":"五言律诗","c":["雨意泄琴床，桃笙骤觉凉。","冲飙方贾勇，藻景荐韬光。","去室怜鸠妇，封闾看蚁王。","青灯可吾伴，黄卷任更长。"]},{"t":"客至","f":"五言律诗","c":["闭关听剥啄，有客款蓬蒿。","谭垒万人敌，词源八月涛。","园蔬供菜甲，盘实饾桃毛。","冷淡琴书味，由来属我曹。"]},{"t":"秋怀二首 其一","f":"五言律诗","c":["送喜得新凉，秋情未憖忘。","弱枝红皱重，平野碧滋长。","林迥蝉初乱，篱疏菊自芳。","吟成转萧瑟，径醉任苍苍。"]},{"t":"秋怀二首 其二","f":"五言律诗","c":["愁绪苦萦人，寒螀殆叵闻。","瓜畴残蔓去，兰畹秀蕤薰。","远水涵秋态，馀霞冠夕曛。","扬扬今夜月，独与广庭分。"]},{"t":"送人之姑苏","f":"五言律诗","c":["吴门千里役，别话不堪闻。","暂发参商叹，长怀星斗文。","菊丛黄彩乱，槐路绿行分。","日冀书邮至，冥鸿接暮云。"]},{"t":"送吴傅朋知盱眙","f":"七言律诗","c":["龟山其下古淮濡，上驷骎骎稳著鞭。","千里八年闻皂盖，九重一旦下青毡。","名郎他日曾趋禁，静镇今朝叠典边。","簪笔侍书公雅意，薰风殿阁待诚悬。"]},{"t":"方福州生日行","f":"七言古诗","c":["雪峰高高雪如许，海门潮生浪吞浦。","郎罢携囝街西东，到处欢然闻好语。","旧日大官多养高，民词狱寄充官曹。","横行阡陌喧夜鼓，唯征关市析秋豪。","只今事事无长蠹，五月政成歌召父。","尺一方来问凤仪，魁三快刷联鸳羽。","三山岌嶪摩曾空，便是方丈蓬瀛中。","他年图画凌烟了，却向山中访赤松。"]},{"t":"谢唐守送朱樱二绝句 其一","f":"七言绝句","c":["铃斋一树滴阶春，翻走髹盘赠野人。","欲进曲生呼伯雅，却无樊素启丹唇。"]},{"t":"谢唐守送朱樱二绝句 其二","f":"七言绝句","c":["乳酪醍醐僻郡无，多酸梅子岂吾徒。","香擎翠笼青冥出，旧事从谁说上都。"]},{"t":"答林神童","f":"七言律诗","c":["快睹终童英妙时，跫然衔袖出明玑。","家声不诧大哉问，文律何愁知者希。","益利锋铓临大敌，养成羽翼看高飞。","红尘可厌忙车马，挹取西山爽气归。"]},{"t":"海棠花二绝句 其一","f":"五言绝句","c":["雨濯吴妆腻，风催蜀锦裁。","自嫌生较晚，不得聘寒梅。"]},{"t":"海棠花二绝句 其二","f":"五言绝句","c":["鸭壳非难致，鲛胎业已成。","夜深宁觅睡，相照月偏明。"]},{"t":"瑞香花","f":"七言律诗","c":["衮衮香毬次第开，结根幽独谢纷埃。","芳蓉妒入鸳鸯社，异馥清传锦绣堆。","睡里魂交非自衍，醒时心赏可无猜。","品题盍在春林石，不是花王喜后来。"]},{"t":"题信州吴傅朋郎中游丝书","f":"七言古诗","c":["上饶氓俗醇且古，千室鸣弦方按堵。","黄堂丈人今循良，河南治平追鼻祖。","讼棠留景分清阴，炉篆方羊燕寝深。","笑谈了却邦人事，游戏翰墨惟书林。","自从真行易篆隶，草圣书绝驰极挚。","游云惊龙初振奇，渴骥怒猊争作势。","臣中第一兹谓谁，寥寥典则其几希。","丈人尺牍妙天下，臧去收拾生光辉。","作古要须从我始，直欲名家自成体。","手追心摹前无人，一扫尘踪有新意。","纵横经纬生胸中，落纸便与游丝同。","缲瓮茧车飞白雪，织檐蛛网破清风。","一行一笔相联属，姿态规抚骇凡目。","临池漫劳三十年，千兔从教后人秃。","旧闻吕向连锦书，百字环写萦发如。","惜哉淟汩已无考，盍使北面称台舆。","独步不复名相甲，端恨二王无此法。","只今四海书同文，使者来求至将押。"]},{"t":"雪诗用晁无咎韵","f":"五言古诗","c":["密雪舞冬昼，祁寒反夏炎。","竹枝低未湿，梅萼瑩先沾。","怯冷昂肩立，欣繁矫首瞻。","随风方北渡，际海必东渐。","轩簸来如掺，缤纷势转严。","枯荄新点缀，曲砌巧增添。","伺隙花穿户，承隅箸插檐。","高飞迷皎鹤，夜影逼清蟾。","砧净绡横石，窗虚粉杂奁。","昆丘千璧碎，武库五兵铦。","烟径杨吹絮，香蹊蝶奋髯。","鲸鲵陆骨腐，鹄鹭野翎爓。","白发秦人遁，厖眉汉尉潜。","渍蚕功孰及，平地瑞初占。","窖卧行人节，门扃志士恬。","已甘穿履困，奚避割毡嫌。","醉慕双螯毕，寒怀五绔廉。","飘飖疑宓女，刻画谢无盐。","河阔凝新浪，峰高失旧尖。","山阴宾欲返，淮右寇将歼。","穆满三章著，宣温五板兼。","君恩捐卫粟，天意绝齐痁。","江上蓑堪画，篱间氅可觇。","客观眸已眩，儿咀手频拈。","足没寻萱屐，腰闲刈藿镰。","马驰毛愈素，乌啄首难黔。","冻折骚人笔，光临织妇幨。","螟牟宁待火，疫疠讵烦砭。","甲长寒蔬细，根肥宿麦纤。","年丰虽欲颂，神助愧江淹。"]},{"t":"前韵虽险用之未尽掇其馀复成三百言","f":"词","c":["一苦寒威重，清晨雨脚□。","严风号宇宙，飞雪下闾阎。","布地盐初撒，穿帷粉乍黏。","裴回轻点袖，萦积满盈檐。","骋巧飘虽急，乘危势或沾。","梨花芳小圃，桂魄射疏帘。","烟湿茶翁灶，竿低酒舍帘。","清泉埋沼沚，苍干耸楩楠。","玉匝齐君履，银封鲁国詹。","盆收新琢璧，阶展未裁缣。","木杪疑飞絮，江干杂秀蒹。","正随云阵合，未放日光暹。","处壮山屠虎，高兴泽殪蚺。","重巅闻折木，邃野绝飞鹣。","隼击翎添厉，鳞藏口敢噞。","狼随姬满驾，鹊集叔才苫。","授简词臣敏，乘车海若谦。","汉传王母绛，周贡嵰山甜。","王脧师方整，高昌众欲熸。","汉光开帝业，苏烈贯兵钤。","豹曳荆人舄，牙抽孙子签。","肤寒方起粟，手坼正忧?。","挟纩冬裘燠，倾罍夜饮厌。","寒光欺宝鉴，素质夺朱綅。","犬喜蹄方逞，儿餐舌未钳。","梅林催皑皑，麦垄长蔪蔪。","罝兔难探穴，叉鱼已溉鬵。","鸱蹲饥愈噪，马缩冻难钳。","见晛将消释，歌诗兴佞憸。","妍辞惭谢客，讵敢示群佥。"]},{"t":"用雪诗韵谢三外弟见和","f":"五言古诗","c":["我昔槜李寓，君方锡山潜。","欲驰咫尺书，駃足无飞廉。","相望参与商，引首徒遐瞻。","朅来萍梗踪，远野得茅檐。","获与谭垒接，何询龟筮占。","青山整烟鬟，澄波开鉴奁。","乔松与怪柏，如虬老龙髯。","悠然一望间，野色皆可觇。","范甑飞埃尘，墨突寒不黔。","好友岂厌频，鸡黍供炊爓。","外家三遗珠，颖脱皆囊尖。","交情谢流俗，不问凉及炎。","著鞭挹清风，从者屡我淹。","高论极根源，师友识所渐。","大略搉治忽，细谈析毫纤。","皮里有阳秋，褒贬追齐歼。","古称学如殖，秋成观执镰。","吾匪董夫子，家居下帷幨。","言经虽败绩，宁防整冠嫌。","抽轧强成章，句鄙不任拈。","骪骳且艰涩，疵瑕费针砭。","君诗粲珠琲，光焰古人兼。","讵覆伧父酒，不道胡儿盐。","陈檄愈头疾，杜词逐寒痁。","轻缣边幅富，健笔锋铓铦。","语句既遒丽，格律何森严。","我穷思已竭，君方涌泉添。","三峡争倒流，未肯波澜恬。","短才愧非正，尚期膏馥沾。","吟罢觉夜永，明窗耿孤蟾。"]},{"t":"读秦本纪","f":"七言绝句","c":["应侯一语幽宣后，长信蒙辜徙萯阳。","秦室无亲类枭獍，借箕谇语亦其常。"]},{"t":"侯生","f":"七言绝句","c":["淮阴束手九江闲，谁信功成颊舌间。","不惜鸿沟分二国，太公今日得生还。"]},{"t":"楚怀王","f":"七言绝句","c":["武关谋诈却称臣，冤魄游魂尚在秦。","墓木萧条冢犹湿，流闻其子作昏姻。"]},{"t":"读战国史","f":"七言绝句","c":["折足黥徒未易欺，箦中死士亦何为。","魏齐断首庞涓死，祸报由来不可知。"]},{"t":"读召公世家","f":"七言绝句","c":["齐晋瓜分四国王，嬴秦为吕芈为黄。","六雄当日皆新主，独有甘棠泽未亡。"]},{"t":"穰侯","f":"七言绝句","c":["推毂曾闻荐武安，威伸三晋走荆蛮。","厕中犬彘图攘夺，犹道藏兵不出关。"]},{"t":"田单","f":"七言绝句","c":["齐主轻忘在莒时，解裘淄水遽相疑。","若无貂勃明勋业，几使功臣枉见夷。"]},{"t":"长平","f":"七言绝句","c":["一败长平振古无，赵邦臣主亦何愚。","当时已中冯亭计，犹自区区遣郑朱。"]},{"t":"春申君","f":"七言绝句","c":["珠履三千尽在门，争无国士解衔恩。","棘门难作无遗类，死党宁闻报李园。"]},{"t":"题陈体仁判官休斋","f":"七言律诗","c":["翔缨彯组盍中留，绿水芙蓉且漫游。","过耳从教千不是，处心浑欲一宜休。","炉中异馥非多爱，架上新签弗外求。","寂寂掩扉无所事，饱听风竹韵凉秋。"]},{"t":"次韵陈体仁惠诗并示游山诗卷","f":"五言古诗","c":["人生名利场，羁绊无休假。","沉迷雁鹜行，梦寐鸡豚社。","见谓游子欺，更防官长骂。","何如山中乐，松窗肆嘉话。","陈侯青云客，英声蜚日下。","当年金马门，掉鞅示閒暇。","小试芙蓉池，未整骊驹驾。","台岳十日行，樛萝若相迓。","来归探古囊，篇篇可图画。","倾耳金石声，郑卫敢争霸。"]},{"t":"次韵李举之县丞秋日偶成 其一","f":"七言绝句","c":["当年使节反穹庐，解绶归来得少娱。","底事微官又萦缚，强颜文墨受意乌。"]},{"t":"次韵李举之县丞秋日偶成 其二","f":"七言绝句","c":["朝来倾耳得街谈，颇说尘容亦可惭。","从事未知三尺守，醉心空向六经酣。"]},{"t":"次韵李举之县丞秋日偶成 其三","f":"七言绝句","c":["宦途陆陆未回车，秋桂春萝总负渠。","目送飞鸿千里去，故山应草绝交书。"]},{"t":"次韵李举之县丞秋日偶成 其四","f":"七言绝句","c":["笔底渊源万顷多，卷中句法不随波。","覃思正作青云计，寡和聊成白雪歌。"]},{"t":"次韵题谢景思少卿药寮","f":"七言律诗","c":["壮岁挥金迈二疏，眼看馀子伏盐车。","芷兰清馥浑纫佩，芝朮新苗几荷锄。","剩作好诗传近体，谁言巧宦胜闲居。","北窗睡起琴声寂，便若身登太皞墟。"]},{"t":"蔡瞻明寺丞有诗见简次其韵","f":"七言律诗","c":["漱芳倾液饱心胸，久矣高名在郢中。","遂请丛祠方养气，卜居萧寺且谈空。","结交许入芝兰室，招隐奚须桑苧翁。","妙语鼎来惊创见，益惭白豕过河东。"]},{"t":"酬李举之","f":"七言律诗","c":["象载凝华落笔工，一时英妙盍居中。","交情耐久惟同味，诗意求新更凿空。","挥麈宁谈阿堵物，联珠不数嗫嚅翁。","文成间被鸡林得，复有声名到海东。"]},{"t":"次韵曹功显都承赏梅","f":"七言律诗","c":["纷纷凡卉怯严冬，独有清姿对雪中。","拂幌更宜妆妩媚，巡檐谁惮履穿空。","南来未见传声使，东望方思避俗翁。","闻道联镳得幽趣，无因同醉玉堂东。"]},{"t":"次韵李举之立春四绝句 其一","f":"七言绝句","c":["东皇先遣雪清尘，一夜山川眼界新。","共喜太平今有象，更将歌舞为迎春。"]},{"t":"次韵李举之立春四绝句 其二","f":"七言绝句","c":["三冬文史总空虚，独有施行宽大书。","坐对南墙千个竹，何妨留客煮园蔬。"]},{"t":"次韵李举之立春四绝句 其三","f":"七言绝句","c":["雪后疏梅正压枝，春来朝日已晖晖。","痴儿公事何时了，一醉花前心似飞。"]},{"t":"次韵李举之立春四绝句 其四","f":"七言绝句","c":["他乡春日思如何，屏去茶瓯任睡魔。","且得小窗成好梦，片时江上逐烟蓑。"]},{"t":"次韵蔡瞻明惜花五绝句 其一","f":"七言绝句","c":["底事春愁减玉肌，谁能獭髓为扶衰。","可怜傍巘临池处，非复嫣然一笑时。"]},{"t":"次韵蔡瞻明惜花五绝句 其二","f":"七言绝句","c":["无情谁似东风薄，相见那思雪夜初。","欲把红颜借桃杏，便教枝上白纷如。"]},{"t":"次韵蔡瞻明惜花五绝句 其三","f":"七言绝句","c":["月地云阶满意开，牵花准拟尚裴回。","抗琼解佩已仙去，骇绿纷红徒后来。"]},{"t":"次韵蔡瞻明惜花五绝句 其四","f":"七言绝句","c":["试因子墨赋瑰姿，独记朝容在一披。","著粉直嫌妆太白，只今何似梦中时。"]},{"t":"次韵蔡瞻明惜花五绝句 其五","f":"七言绝句","c":["一声横笛晓林空，知是春风十日东。","来岁花时在何处，探芳还有几人同。"]},{"t":"陈体仁以心清闻妙香作诗惠末利花香次韵为谢 其一","f":"五言律诗","c":["尘劳昏独志，禄利蚕良心。","扫地香一炉，澹然清兴深。","假寐顷刻间，烟霏遂盈襟。","联翩珊瑚钩，逼人何骎骎。"]},{"t":"陈体仁以心清闻妙香作诗惠末利花香次韵为谢 其二","f":"五言律诗","c":["东风将小雨，一夕池中平。","春声在疏竹，琅琅有馀清。","公退远世氛，心地莫与京。","宝薰凝窗牖，为君寻鸥盟。"]},{"t":"陈体仁以心清闻妙香作诗惠末利花香次韵为谢 其三","f":"五言律诗","c":["鼻观拜嘉况，名香如前闻。","尘容方一洗，藻思期三薰。","久坐欣有得，飘飘欲陵云。","都良与迷迭，芳馨此其分。"]},{"t":"陈体仁以心清闻妙香作诗惠末利花香次韵为谢 其四","f":"五言律诗","c":["英英末利花，素蕤馥清晓。","谁将煮水沉，采撷得奇妙。","吾非范蔚宗，品题能了了。","杂佩愧报酬，芜音发嘲笑。"]},{"t":"陈体仁以心清闻妙香作诗惠末利花香次韵为谢 其五","f":"五言律诗","c":["春日紫宸朝，合殿萦天香。","玉笋粲风采，鸡舌相芬芳。","陈侯金闺彦，指期簉鹓行。","安能久郁郁，俛首回刚肠。"]},{"t":"偶得梅一种疏枝清香附萼之花五出与江梅无异但花色微红而五出之上复有一重或十叶或九叶他日皆并蒂双实俗呼为鸳鸯梅昔上林有赵昭仪所植同心梅疑即此也因成四绝 其一","f":"七言绝句","c":["却月凌风一种香，更匀粉面作红妆。","枝头自结鸳鸯社，为倩东风谢海棠。"]},{"t":"偶得梅一种疏枝清香附萼之花五出与江梅无异但花色微红而五出之上复有一重或十叶或九叶他日皆并蒂双实俗呼为鸳鸯梅昔上林有赵昭仪所植同心梅疑即此也因成四绝 其二","f":"七言绝句","c":["重重香蘤故多情，索笑初闻带薄酲。","翻恨前村雪深处，一枝幽独太憨生。"]},{"t":"偶得梅一种疏枝清香附萼之花五出与江梅无异但花色微红而五出之上复有一重或十叶或九叶他日皆并蒂双实俗呼为鸳鸯梅昔上林有赵昭仪所植同心梅疑即此也因成四绝 其三","f":"七言绝句","c":["客子逢花心欲灰，异方初见眼还开。","故应临水横斜日，曾作于飞一念来。"]},{"t":"偶得梅一种疏枝清香附萼之花五出与江梅无异但花色微红而五出之上复有一重或十叶或九叶他日皆并蒂双实俗呼为鸳鸯梅昔上林有赵昭仪所植同心梅疑即此也因成四绝 其四","f":"七言绝句","c":["开花已作鸳鸯侣，著子还成鸿雁行。","旧日同心上林种，至今千载亦流芳。"]},{"t":"次韵蔡瞻明登巾山三绝句 其一","f":"七言绝句","c":["朝来爽气冠曾丘，急雨惊风正麦秋。","要得云轩聊放目，何妨松径暂低头。"]},{"t":"次韵蔡瞻明登巾山三绝句 其二","f":"七言绝句","c":["名缰局促祇怀惭，飘忽熙春月过三。","矫首白云千里外，此心无日不江南。"]},{"t":"次韵蔡瞻明登巾山三绝句 其三","f":"七言绝句","c":["好句联翩见未曾，品题今日欠钟嵘。","登临自有江山助，岂是胸中不得平。"]},{"t":"得二弟消息","f":"五言律诗","c":["倚栏春昼静，花柳自芳香。","消息三州远，尘埃两地忙。","鹊声传近喜，鸿影忆初行。","抄得新书策，归时补墨庄。"]},{"t":"次韵李举之风雨中书事四绝句 其一","f":"七言绝句","c":["挂壁鸣琴久断弦，强反书帙本相便。","词源顾我非流峡，藻思如君已掞天。"]},{"t":"次韵李举之风雨中书事四绝句 其二","f":"七言绝句","c":["雨势风声何太雄，群山答响乱贲镛。","青奴今夕安用汝，玉友此时留得侬。"]},{"t":"次韵李举之风雨中书事四绝句 其三","f":"七言绝句","c":["怒号通夕搅空虚，好梦那能到玉除。","枕上泰然无一念，只愁雨滴架中书。"]},{"t":"次韵李举之风雨中书事四绝句 其四","f":"七言绝句","c":["向晓登楼凭小栏，萧然归兴在江干。","痴儿未了公家事，且把云山子细看。"]},{"t":"次韵蔡瞻明秋园五绝句 其一 鸡冠","f":"七言绝句","c":["芥毛金爪勇难干，肯作霜花对乍寒。","若说乘轩有痴鹤，司晨如此合峨冠。"]},{"t":"次韵蔡瞻明秋园五绝句 其二 金凤","f":"七言绝句","c":["翔仞当年览德辉，传芳花品未思归。","晚来雾鬓凭轩处，直恐金翘相对飞。"]},{"t":"次韵蔡瞻明秋园五绝句 其三 芭蕉","f":"七言绝句","c":["泽兰萱草比多言，谓汝分阴久夺鲜。","政恐淇园修竹劲，不如秦岭老松坚。"]},{"t":"次韵蔡瞻明秋园五绝句 其四 芙蓉","f":"七言绝句","c":["高标幽艳自宜霜，弱草繁葩莫中伤。","肯与红莲媚三夏，要同黄菊向重阳。"]},{"t":"次韵蔡瞻明秋园五绝句 其五 金钱","f":"七言绝句","c":["临风裛露早秋天，范出南金色更鲜。","若向东篱比标格，定知花市不言钱。"]},{"t":"宿佛窟寺","f":"五言律诗","c":["篮舆登佛窟，高阁望中清。","古木尔许荫，飞泉无限声。","雨消今日暑，云作晚来晴。","独对青山久，相逢如有情。"]},{"t":"过瑞岩寺示胜上人","f":"五言律诗","c":["逗晓乱山中，来寻古佛宫。","荷间留夜雨，松下进秋风。","瑞气旧如许，岩姿今亦同。","惺惺有盘石，应记主人公。"]},{"t":"惺惺石","f":"五言绝句","c":["簿领久沉迷，谁能不忍欺。","我来惭此石，拈出问吾师。"]},{"t":"滴滴泉","f":"五言绝句","c":["石罅来泉滴，松风杂涧声。","天明有公事，还忆此时清。"]},{"t":"题灵石寺并简景思","f":"五言律诗","c":["闻道飞来石，当年却畔亡。","烟杉行客路，风竹护禅房。","有酒对玉麈，无诗夸锦囊。","尘缨自羁束，真赏负山光。"]},{"t":"夜饮药寮次景思韵","f":"七言律诗","c":["主人知我乐郊居，药圃嘉招走尺书。","笑语池边欣促席，醉归林下却肩舆。","正闻雁过猿啼后，更是风清月白初。","见说长安消息近，却须高兴谢鲈鱼。"]},{"t":"题景思水芝亭","f":"五言律诗","c":["远意閟千云，亭幽不受尘。","来为池上客，本是社中人。","影密龟鱼荫，花开鸥鹭驯。","买山如遂志，应许卜比邻。"]},{"t":"黄岩道中","f":"五言律诗","c":["两日黄岩县，纷然百虑侵。","乍听幽鸟语，复起故园心。","冒热度峻岭，惮劳休茂林。","潮来知海近，三岛可能寻。"]},{"t":"过妙缘寺听怀上人琴","f":"五言律诗","c":["断涧复危岑，红尘且满襟。","疾驱触炎热，小憩得禅林。","煮茗对清话，弄琴知好音。","秋风不借便，去辙已骎骎。"]},{"t":"行县道中寄曾谹父","f":"七言律诗","c":["云山初见非昔游，一瞬不许回双眸。","二年佐州已强半，七月行县难罢休。","溅溅微溜响萦谷，薿薿多稼光盈畴。","兵厨愿留一樽酒，霜螯醉嚼期中秋。"]},{"t":"登宁和岭","f":"五言律诗","c":["初识宁和岭，有怀占梦时。","闻诗千里隔，断织九京悲。","草木应相记，烟云浑异宜。","西风袭怀抱，泪睫不胜垂。"]},{"t":"怀孙邦求","f":"七言律诗","c":["酒开桑落泛觥觓，行子驱车恨不留。","雁塔自是丈人行，麟台更参儒者流。","官居二年有十月，别思一日真三秋。","冰轮今已可人意，何时来赏城东楼。"]},{"t":"宿大龙山寺赠海上人","f":"五言律诗","c":["看山论旧事，拂石认前题。","雨滑苔径阻，云收松峤迷。","三秋文豹隐，一夜寒螀啼。","又复问程去，清游怀虎溪。"]},{"t":"大龙山五咏用家君所和胡别驾韵 其一 经藏","f":"五言绝句","c":["万法俱一空，忘筌亦忘字。","勿置齿牙间，回观方寸地。"]},{"t":"大龙山五咏用家君所和胡别驾韵 其二 龙祠","f":"五言绝句","c":["夹日授五飞，论功中兴主。","宛宛龙父尊，兹山职霖雨。"]},{"t":"大龙山五咏用家君所和胡别驾韵 其三 密室","f":"五言绝句","c":["小室坐蒲团，死灰念不作。","所以护明珠，精修企先觉。"]},{"t":"大龙山五咏用家君所和胡别驾韵 其四 小池","f":"五言绝句","c":["山椒有龙湫，清泉日夜流。","疏岩作方沼，漱甘非外求。"]},{"t":"大龙山五咏用家君所和胡别驾韵 其五 汤炉","f":"五言绝句","c":["蟹眼候松风，云腴挟霜月。","炉下岂常炎，灰飞即烟灭。"]},{"t":"怀李氏昆弟二十韵","f":"五言古诗","c":["城南两佳士，英躔名硉矹。","相之妙才具，玉笋班中阙。","胡为彯长缨，去去事輗軏。","举之登词坛，龙虎榜未揭。","归循南陔兰，不使芳馨歇。","胸中蟠五车，一一思英发。","有中清庙瑟，审声知度越。","我来贰银菟，接袂俱墨发。","情期胶漆坚，门受车马谒。","笔阵几鏖战，君盈我先竭。","别来勤相思，十日倏飘忽。","迟明蒙嚣尘，毕景迈崷崒。","跻高怯肩舆，挹秀欣拄笏。","泉清甘著齿，岩幽冷萦骨。","西风涌波澜，极望际溟渤。","是中三神山，缥缈云出没。","问津旧乘槎，引舟今舍筏。","俛首倾缥瓷，独醉径兀兀。","起看天宇开，诗成走邮卒。","归欤及中秋，高楼共嘉月。"]},{"t":"宿广润寺书伦上人灵云庵","f":"七言律诗","c":["宝地深深俯碧潭，有僧酌茶延我谈。","千岩状秀蹑风磴，万竹含翠藏云庵。","西来指柏本无著，一见悟桃须再参。","登临已是秋欲半，霜叶枝头才两三。"]},{"t":"摘星岭","f":"七言律诗","c":["披山凿道何崄巇，上摘星汉摩虹霓。","七襄终日往曾问，一握去天今可跻。","叱驭已排萝蔓去，下车不复烟云迷。","举头此际长安远，愿借六翮凌丹梯。"]},{"t":"交翠亭 其一","f":"五言绝句","c":["三十年中事，鸾栖筑小亭。","寒声长新箨，清閟拂疏棂。"]},{"t":"交翠亭 其二","f":"五言绝句","c":["水转前时绿，山浓远处青。","重来勤问讯，此别记秋萤。"]},{"t":"三瑞堂","f":"五言律诗","c":["久矣驰魂梦，今登三瑞堂。","故山有乔木，近事话甘棠。","展骥惭充位，占熊忆问祥。","白云留未去，极望是吾乡。"]},{"t":"留别县僚","f":"七言律诗","c":["满城鼓吹出林坰，珍重来思此日情。","共说栖鸾留政迹，自怜展骥坠家声。","一时宦侣推儒雅，百里民编乐治平。","山意川容若相挽，不堪整驾问归程。"]},{"t":"过梁王寺书家君祠堂","f":"七言绝句","c":["生还未列麒麟画，旧德犹怀鸾凤栖。","共问翰林今孰似，凛然眉宇染风㙠。"]},{"t":"山行遇雨","f":"七言律诗","c":["天公作意轰雷霆，风雨骤至神如兵。","翻手为云只俄顷，举头见日尤精明。","蚁君一战方奏凯，鸠妇复还已和鸣。","税驾欲投佳处所，林间隐隐疏钟声。"]},{"t":"蔡瞻明以诗还行邑鄙卷次韵谢之","f":"七言律诗","c":["凉秋野趣已萧骚，方驾看山念我曹。","十日空归才每下，一篇来况曲弥高。","词华若我惭雌霓，笔力惟公掣巨鳌。","欲作歌诗兴协律，清朝今日有王褒。"]},{"t":"酬李举之用前韵见寄","f":"七言律诗","c":["阅尽千峰不惮劳，归来文墨厌官曹。","浮槎问汉秋期近，埋剑冲星夜气高。","那复精思如吐凤，初无壮志欲乘鳌。","诗坛轩轾归题品，滥得阳秋一字褒。"]},{"t":"褒字诗已得十二章请各赋其一以足巨鳌","f":"七言律诗","c":["纷纷吏道誇吹毛，未肯留心效此曹。","象齿好辞降二妙，鲈鱼归思羡三高。","吟毫未秃一千兔，诗轴须联十五鳌。","敢道严霜起中夏，益知趁韵有龙褒。"]},{"t":"次韵蔡瞻明木犀八绝句 其一","f":"七言绝句","c":["谁为花王定等差，清芬端合佩金犀。","上林他日移根去，应记诗仙綵笔题。"]},{"t":"次韵蔡瞻明木犀八绝句 其二","f":"七言绝句","c":["香清为借三秋露，葩绚宁禁五日风。","俯对猗兰振寒绿，静看飞叶陨轻红。"]},{"t":"次韵蔡瞻明木犀八绝句 其三","f":"七言绝句","c":["风流直欲占秋光，叶底深藏粟蕊黄。","共道幽香闻十里，绝知芳誉亘千乡。"]},{"t":"次韵蔡瞻明木犀八绝句 其四","f":"七言绝句","c":["笑含菊彩媚疏篱，巧作葵妆傍曲池。","颜色从他矜速肖，芬馨如此孰争驰。"]},{"t":"次韵蔡瞻明木犀八绝句 其五","f":"七言绝句","c":["心禀犀文饶地力，体薰蟾影夺天香。","图形好命丹青手，絺句须烦锦绣肠。"]},{"t":"次韵蔡瞻明木犀八绝句 其六","f":"七言绝句","c":["广寒秋桂映天池，休说当年折得时。","韵胜今逢岩下种，价高宁靳橐中资。"]},{"t":"次韵蔡瞻明木犀八绝句 其七","f":"七言绝句","c":["簪鬓新枝立晚晴，淡妆异馥称双清。","梦魂不记前来事，愁逐江潮日日平。"]},{"t":"次韵蔡瞻明木犀八绝句 其八","f":"七言绝句","c":["黄绢家声映古今，随和发彩惊词林。","高楼宴坐清商晚，独向此花垂意深。"]},{"t":"次韵李相之观溪涨二首 其一","f":"五言律诗","c":["愁霖方注射，骇浪忽冲斜。","宿鸟行惊雁，游鱼目失虾。","夕波奔析木，春涨过桃花。","沸渭今如此，谁乘犯斗槎。"]},{"t":"次韵李相之观溪涨二首 其二","f":"五言律诗","c":["风声随雨急，水势满川黄。","巨舰困澎湃，穷阎悲混茫。","为鱼怀洛汭，揵竹谢宣防。","共徯阴云卷，冰轮替戾冈。"]},{"t":"次韵酬丁致远司户","f":"七言律诗","c":["翰墨场中识面初，珠玑粲粲似相如。","盍簪多士登台省，却掾诸曹亲簿书。","白社不妨闲泚笔，赤城更好命巾车。","寸心淟汩方茅塞，快读新诗得剪除。"]},{"t":"次韵蔡瞻明江楼秋晚二首 其一","f":"五言律诗","c":["斜照穿林迥，归云敛岫迟。","蜗文寒壁篆，蛛巧暮檐丝。","待月是愁处，对山无倦时。","掀髯阻谈绮，细读寄来诗。"]},{"t":"次韵蔡瞻明江楼秋晚二首 其二","f":"五言律诗","c":["竹外秋风急，楼头夕霭微。","遣怀须命酒，怯冷几更衣。","严鼓萦城去，轻舟劈浪归。","登临多少意，坠叶满庭飞。"]},{"t":"九日官舍种竹","f":"七言律诗","c":["独整陈编对北窗，烟云浑欲助凄凉。","庭前且使竹交翠，篱下从他菊自黄。","远官只今同旅泊，壮怀谁复问行藏。","携壶已失登临便，不待微吟恨夕阳。"]},{"t":"天台道中","f":"五言律诗","c":["滩声因雨急，山势向云斜。","橘绿谁能画，枫丹远似花。","舂锄怀浅水，郭索上寒沙。","渐听鸣梭近，林中三数家。"]},{"t":"赤城","f":"七言绝句","c":["平生几读兴公赋，今日霞标对赤城。","此是南门入山路，山祇乞我一番晴。"]},{"t":"玉京洞","f":"七言绝句","c":["飙轮曾此宅灵仙，洞府今称第六天。","规往不辞萝蔓险，回看云物起琼田。"]},{"t":"国清寺","f":"五言律诗","c":["绀宇今方盛，名知国已清。","万松九里影，双涧四时声。","杖策将穷览，巾车不计程。","登堂山更好，人去晓猿鸣。"]},{"t":"清音亭","f":"五言律诗","c":["久坐俯潺湲，流清诗思悭。","跳珠鸣藓石，淙玉下松关。","此日耳尘静，几人心地闲。","抽琴作新曲，归去要怡颜。"]},{"t":"禅林寺","f":"五言律诗","c":["振策快秋晴，伽蓝倚翠屏。","看云不留瞬，对竹已忘形。","银地声千载，虹桥拱百灵。","至今钟磬响，如讲净名经。"]},{"t":"山中阻雨欲登华顶峰而不果","f":"五言古诗","c":["昔闻天台山，一万八千丈。","层峰目华顶，魂梦几驰想。","朅来乘清秋，明发将独往。","小雨巧作难，祥云约仍爽。","风磴渍苔藓，霜崖乱榛莽。","峥嵘一何峻，梯空不可上。","便思捐竹舆，徐行倩藤杖。","老僧挹而言，兹山韬万象。","举头天宇逼，寓目岩扉敞。","重溟倒寒影，万壑振幽响。","峡迥啼猱猿，林高陨楂橡。","仙袂挹浮丘，飘然顿尘网。","今兹风雨时，烟雾接穹壤。","劲寒或薄人，跬步迷俯仰。","不如游石梁，重来事真赏。","斯言既纚纚，诚哉非我诳。","俗驾为之回，芜音不堪榜。","寄声山中灵，心期空鞅鞅。"]},{"t":"石桥","f":"五言古诗","c":["悬磴跨幽崖，奔流漱深壑。","宛然卧苍龙，天巧谢镌凿。","万木森前山，笙竽真籁作。","长啸斥猩猱，来巢怖乌鹊。","莓苔助危梁，下瞰心胆落。","横前限翠屏，峭壁旁如削。","于此判尘凡，只尺遂绵邈。","飞锡蹑空虚，楼台变林薄。","宝辉觌华灯，金翰过神雀。","二年佐铜虎，渠能解羁络。","来烹紫云腴，寒瓯散葩萼。","奇事订前闻，诗成识层阁。"]},{"t":"雨中宿万年寺","f":"七言律诗","c":["梦回深夜耿秋灯，泉窦争流一味清。","过雁不闻天外影，寒松长送枕边声。","饕风可但久无赖，急雨那能便寝行。","已问琼台双阙路，此心何必羡层城。"]},{"t":"闲上人览众亭","f":"七言律诗","c":["篮舆行尽白云层，来款禅居得小亭。","乱石引泉归曲涧，寒风吹雨过中庭。","四旁野色朝昏别，一览岩姿远近青。","宴坐蒲团作何想，光阴不复问尧蓂。"]},{"t":"贺子忱吏部抱膝庵","f":"七言律诗","c":["主人蚤岁抽华簪，隐居时作梁父吟。","于今松窗在人境，空有蕙帐留烟岑。","风来翠筱自摇玉，秋著黄花仍散金。","拂拭尘埃记行役，兴来命酒还孤斟。"]},{"t":"桐柏观","f":"七言律诗","c":["屹然双阙峙琼台，仰见彤云郁郁开。","三井穷源知海眼，六符垂象应天台。","松杉满道欣初过，芝朮何年得自培。","更听鸣泉杂风籁，直疑笙鹤紫霄来。"]},{"t":"众妙台","f":"七言绝句","c":["白云仙迹纪琅函，三体丹书宝翠岚。","欲问仕涂今捷径，不须高价借终南。"]},{"t":"石道士妙声堂","f":"五言律诗","c":["泉溜古今同，临流万虑空。","采芝归绝嶂，添竹映疏丛。","影漾高秋月，声宜深夜风。","真清长在耳，何用抚孤桐。"]},{"t":"仙坛院","f":"五言绝句","c":["蕉闻王子晋，云卧夜吹笙。","控鹤冲天去，松风千古声。"]},{"t":"天台观","f":"七言律诗","c":["芝田环拱碧崔嵬，流瀑高从天际来。","飞沫有风长是雪，寒声无日不如雷。","岩前八桂人谁折，溪畔千桃路未开。","便觉仙都清昼永，翻愁归路染黄埃。"]},{"t":"刘阮洞","f":"七言律诗","c":["桃花当日未成蹊，已有幽禽语翠微。","楚峡行云空入梦，秦台鸣凤要同飞。","仙家长若三春好，人境何知万事非。","访问丘园荒旧迹，却应回首悔来归。"]},{"t":"赠护国昌老","f":"五言律诗","c":["缓辔到禅扃，高谈得细听。","茗花泛轻碗，烟篆度虚棂。","门外云千片，轩中水一瓶。","我来无好语，留此待丹青。"]},{"t":"慈云祖老相邀至悠然阁倦不克往","f":"五言绝句","c":["几日陟云烟，危峰懒著鞭。","聊将临别意，为我谢悠然。"]},{"t":"明岩寺","f":"五言律诗","c":["路转霞标外，云开绶带前。","几层山底屋，一线竹间泉。","洞口石孤耸，岩头峰倒悬。","故应风雨际，行子总回鞭。"]},{"t":"寒岩寺","f":"五言律诗","c":["峭壁插青冥，层岩覆化城。","空中清磬发，幽处慧灯明。","万瓦足云气，四檐无雨声。","丰干不饶舌，此地孰知名。"]},{"t":"宁国寺","f":"五言律诗","c":["几日山南北，端期汗漫游。","水痕秋雨过，竹色晓烟收。","宦海何时了，僧房为少留。","却寻归去路，馀兴谩回眸。"]},{"t":"晓发秦安驿","f":"五言律诗","c":["秋梦不能晓，起行山径迷。","小车惊宿鹭，列炬误鸣鸡。","冷觉霜华重，光瞻斗柄低。","金庭有佳处，芳桂想幽栖。"]},{"t":"以糟蟹送曾守","f":"七言律诗","c":["太湖九月霜波寒，郭索不幸逢渔蛮。","谁令骨醉糟丘里，使我涎流书卷间。","黄堂丈人思幼玉，耳边不复亲丝竹。","一杯聊使破愁颜，要遣诗情踵山谷。"]},{"t":"得景严弟书","f":"五言律诗","c":["往年同入洛，此日各监州。","惯见浮云改，相思野水流。","有书将远意，何处话新愁。","莫为痴儿事，乾萤满案头。"]},{"t":"梦中送妙兴寺僧","f":"七言绝句","c":["西望霞光东望云，划然晴晦此区分。","小桥过尽盘龙险，回首高人多谢君。"]},{"t":"次韵曾宏父探梅未开","f":"五言律诗","c":["梅枝浑待雪，山意渐呼风。","欲索檐间笑，那忧径外穷。","英辞窥玉洁，拙句愧雷同。","只恐花开日，纶言下法宫。"]},{"t":"招曾宏父待雪","f":"五言律诗","c":["欲把诗催雪，先将酒送寒。","冻云方作意，微霰已开端。","目断乡城远，心惊岁事阑。","拟同今日醉，待取玉花看。"]},{"t":"次韵钱处和运使郡斋晚集","f":"七言律诗","c":["风声止雨岁云暮，雪态兼云昼欲昏。","共喜高轩归别墅，肯临画戟对清樽。","埋轮前事空豺路，授简英辞踵兔园。","是处梅花寝消息，更凭玉藻为招魂。"]},{"t":"游盖竹洞","f":"七言律诗","c":["晓出山城故著鞭，荒荒寒日满晴川。","幽栖未卜诛茅地，乘兴来登盖竹天。","霜凝阴崖疑积雪，云跻重障杂飞烟。","洞门今古无关键，俗客那能见列仙。"]},{"t":"仙居道中","f":"五言律诗","c":["雪霙方瑞腊，雨势欲凋年。","此日信泥轼，来风侵坐毡。","为官浑漫尔，行邑又徒然。","为报仙居令，无劳负弩前。"]},{"t":"寄吴明可正字","f":"五言律诗","c":["岁晚仍多病，春来尚异乡。","愁城谁与破，谈垒漫相望。","体怯山岚重，心随驿路长。","后亭梅若放，为寄一枝香。"]},{"t":"次韵范子芬雪中同访曹功显","f":"七言律诗","c":["明朝春琯欲飞葭，腊里重看舞雪斜。","笔下百篇非事业，樽前一醉即生涯。","初疑高柳狂吹絮，却伴寒梅好放花。","踏冻不辞方驾远，闭门留客更谁家。"]},{"t":"忆梅呈曾宏父","f":"五言律诗","c":["重忆东城路，盈盈十里梅。","弥旬阻风雪，几处杂尘埃。","已是春移律，何时酒泛杯。","好花那忍落，直待使君来。"]},{"t":"题王氏秀野堂","f":"五言律诗","c":["饱闻居处好，远意快心胸。","树接高低影，山分朝暮容。","佳时能自适，闲客几相从。","勿讶题诗晚，新来百事慵。"]},{"t":"除夜怀景严弟并寄景卢","f":"五言律诗","c":["远乡劳薄宦，綵服共思亲。","耿耿胸中事，纷纷眼底尘。","与谁同别岁，到此两迎春。","独有还家梦，书窗一笑新。"]},{"t":"次韵曾宏父欲赏山宫梅花","f":"七言律诗","c":["黄堂清兴动官梅，遥望花林首屡回。","命驾许同狂客往，舒笺频有好诗催。","空怀月观横千影，趁取山宫举一杯。","为语东皇相假借，莫教零乱点苍苔。"]},{"t":"宏父见招赏梅时范子芬欲行","f":"七言律诗","c":["翩翩画戟对春光，命客重登千仞冈。","坐上行人倾别酒，花前小雨伴啼妆。","雪肤不为轻寒瘦，玉骨何如昨夜香。","丽句竞传新乐府，谁誇何逊在维扬。"]},{"t":"次日宏父携家出游而小雨新晴","f":"七言律诗","c":["山头霞彩发天光，初日曈昽射短冈。","莫使吹箫寻古曲，直宜点额作新妆。","不禁风雨飞来急，颇觉园林减却香。","花下凌波奏奇舞，腰支尺六笑垂杨。"]},{"t":"丁卯正月十六日作舞漪亭于池上尽废蔬畦植花数十本","f":"七言律诗","c":["二年倥偬缓归期，漫作新亭接舞漪。","举郡定嗤推不去，故山已讶到何迟。","园官不属藜苋腹，花史好呈桃李姿。","待得浮萍是飞絮，谁能爱树一相思。"]},{"t":"检校园花","f":"五言古诗","c":["往夏新阁成，拔去园中葵。","万花间千蕊，十夫劳徙移。","群香颇猗狔，密影初参差。","烈日吁可畏，时雨不能滋。","未秋叶先陨，欲冬柯已萎。","虚蒙灌溉恩，无复嫣然姿。","啅雀飞且止，不肯登空枝。","寒螀守枯荄，未忍相弃离。","永怀斩新日，岂料憔悴期。","谁呼殷七七，来伴红裳儿。","金鼎一剂药，返魂庸可追。","春来作高亭，绿沼扬清漪。","旧蹊类陈迹，远圃分芳蕤。","结根旬浃间，生意浑熙熙。","微白李赋质，小红桃入肌。","柳条无颜色，已含烟雨眉。","游蜂相召引，有底渠先知。","地力固自若，大钧不偏私。","竞秀非机巧，向衰非钝迟。","万物理固然，飏芬须得时。"]},{"t":"添竹","f":"五言律诗","c":["添竹乘春力，期君共岁寒。","青青怀特操，碌碌愧粗官。","尚有哦诗日，尤胜借宅看。","他时谁检校，何处报平安。"]},{"t":"次韵景思谢送四时纂要并惠乳泉且许见顾 其一","f":"七言绝句","c":["断壶食郁遵时令，莲芡櫜韬辨土宜。","若解养生供伏腊，自然卜筑数期颐。"]},{"t":"次韵景思谢送四时纂要并惠乳泉且许见顾 其二","f":"七言绝句","c":["我无卮茜等通侯，不作多田望蓐收。","松菊漫成三径梦，烟蓑已失五湖秋。"]},{"t":"次韵景思谢送四时纂要并惠乳泉且许见顾 其三","f":"七言绝句","c":["青编送似补山房，妙语相酬掩夜光。","盗瓮不须睎吏部，将军何日命元方。"]},{"t":"送范子芬赴浙东机幕","f":"七言律诗","c":["男儿三十富春秋，况复才华出辈流。","传家不坠右丞相，入幕少佐东诸侯。","梅花颇惜诗人去，草色正牵行客愁。","修禊兰亭访陈迹，应怀同醉仲宣楼。"]},{"t":"送季元衡教授赴调","f":"五言律诗","c":["三年淹讲席，斗酒动离情。","此去登台省，诸公熟姓名。","骅骝看地绝，鸾凤为时鸣。","春日西湖上，烦君一寄声。"]},{"t":"送石初平归四明","f":"七言律诗","c":["析别梁溪七换春，海边相过意能勤。","裤襦不羡千金子，简策无惭万石君。","豪气掀雷须给札，他时修月待挥斤。","镂衢又揖东风去，情话无人可夜分。"]},{"t":"送李相之提干闽中十二韵","f":"五言古诗","c":["官柳讫春事，落絮东复西。","门外高轩过，行行将何之。","七闽绣衣属，非如州县卑。","少留长者辙，酌酒语别离。","五年官他壤，一面即故知。","辩囿麈仍落，诗坛襟屡题。","撞钟问今古，邃然五总龟。","迢迢千里去，风过衫裳吹。","我亦及更书，归耘楚江涯。","河梁携手叹，参辰后难期。","曼倩宁自衒，长卿固同时。","征途慎勿遽，会看轺车驰。"]},{"t":"题左达功秀才桂香斋","f":"五言古诗","c":["小斋面蓬瀛，昂霄得双桂。","黄卷对圣贤，欣然有馀地。","笔端妙言语，挟此波澜势。","荧荧百鍊刚，自是青萍器。","冲星不我识，铅刀且争利。","于今修月手，益振陵云气。","明年广寒宫，声名郤诜似。","归来八桂乡，浮丘挹仙袂。"]},{"t":"还李举之太平广记","f":"七言绝句","c":["稗官九百起虞初，过眼宁论所失诬。","午枕黑甜君所赐，持还深愧一瓻无。"]},{"t":"酬光吉叔用前韵见寄","f":"五言律诗","c":["怨鹤今谁侣，驯鸥讵可亲。","颇思同渌酒，久已厌红尘。","归梦常通夕，微吟漫惜春。","床头易在否，触手不应新。"]},{"t":"次韵蔡瞻明雨中书怀","f":"七言律诗","c":["梅雨冥冥晴复阴，小轩终日起归心。","自怜宦业初何补，独喜交情久益深。","忆得微醺看锦瑟，愧无好语比南金。","青山千里江南路，它日邮签幸见寻。"]},{"t":"赠传神陈秀才","f":"五言律诗","c":["举世人心别，端如面不同。","山川险难测，笔墨思何工。","未索形骸外，聊先阿堵中。","自怜无骨相，不到汉南宫。"]},{"t":"次韵向宪见赠三首 其一","f":"五言律诗","c":["理财无管晏，言利析秋豪。","吐论千人废，摩空六翮高。","未簪安世笔，先佩吕虔刀。","楚泽东风劲，宁辞揽辔劳。"]},{"t":"次韵向宪见赠三首 其二","f":"五言律诗","c":["四望荒楼观，登高动土思。","山川相映带，桃李已纷披。","汉节人重仰，黄陂世莫窥。","三章堆锦绣，唐突古西施。"]},{"t":"次韵向宪见赠三首 其三","f":"五言律诗","c":["河东空有赋，人不道扬雄。","贵贱云泥隔，寅缘井邑同。","平番依列宿，谈笑霁威风。","终赖帡幪力，能成尺寸功。"]},{"t":"次韵向宪道中偶成","f":"五言律诗","c":["四牡驰原隰，侯邦害必除。","疲民端可念，茅舍未如初。","消息三春异，创痍二纪馀。","君王心在远，谕意倚相如。"]},{"t":"闻景严弟迁西掖并寄景卢","f":"七言律诗","c":["俛仰梁溪岁几寒，向来墨沼已中乾。","传家紫橐荣三子，得路青云喜二难。","爵位方知稽古力，论思当使覆盂安。","自怜骨相宜尘土，那得丝言动笔端。"]},{"t":"次韵向宪留题荆门惠泉卒章见及","f":"七言古诗","c":["对泉一洗心如水，诵诗三叹颡有泚。","字比渴骥骎骎来，文如翠潋鳞鳞起。","皇华辙迹环诸道，济物良筹载襟抱。","双泉复见等故人，竹马儿童半羸老。","吾君丰泽要下流，惭愧长澜力不侔。","一方始此一滴润，千亩长有千钟收。","去瘼未尽惠未施，可使剜肉生新痍。","尘埃满面语甚恶，虚辱逢人统项斯。"]},{"t":"独步惠泉用石刻中韵","f":"五言古诗","c":["拂崖看古字，倚策仰前英。","雕章细细读，清思源源生。","文传岘山石，句敌渼陂行。","一字或华衮，五言有长城。","林蝉众作噪，下里羞混并。","坐令蕞尔国，宇内浑知名。","兹泉发地脉，有玉潜山庭。","神龙职何护，老蚌呈煌荧。","楚人力水耨，倚沼仍畦瀛。","觱沸昼复夜，输出无穷声。","演迤清汉接，旋折数日程。","膏润亘原陌，谷价年年平。","非才忝敷惠，下考乃为荣。","疲民未击壤，循吏难联横。","独行挹清泚，谁与论丹诚。","销忧赖季雅，遣兴烦客卿。","信美非吾土，千古仲宣情。"]},{"t":"杨元素题蒙泉诗云源有雌雄分碧白注谓南泉色白为雌因为之解嘲二绝句 其一","f":"五言绝句","c":["小孤宁有匹，织女自无家。","浪比人间世，增添白玉瑕。"]},{"t":"杨元素题蒙泉诗云源有雌雄分碧白注谓南泉色白为雌因为之解嘲二绝句 其二","f":"五言绝句","c":["雄风波不动，雌霓影空垂。","欲洗蒙泉谤，须删蜀客诗。"]},{"t":"曲水","f":"七言绝句","c":["杯去浑无勇退时，偶然遇坎亦安之。","不教坐有独醒客，便与投醪倒接篱。"]},{"t":"金莲","f":"七言绝句","c":["绿衣黄里水苍笄，朝暮凌波步武齐。","一种清高乐泉石，移根不肯污涂泥。"]},{"t":"古柳","f":"七言绝句","c":["异时古木蔽岩阿，去盗来兵厄斧柯。","老柳如龙寿千百，独全煨烬傲清波。"]},{"t":"同姚当可胡元质钱舜仁张昭甫游上泉","f":"五言古诗","c":["避暑远簿书，寻幽踏菅蒯。","寒泉浮玉根，巨石开眼界。","灵湫几千年，洗尽尘土碍。","老藤走长蛇，茂木攲翠盖。","扫叶坐水旁，可喜此风快。","炎云不能神，潜虬秘奇怪。","满酌白玉钟，咽甘犹沆瀣。","何如习家池，举鞭同倒载。"]},{"t":"次韵朱宣州见寄","f":"七言律诗","c":["十载萧萧麋鹿姿，那知出守得同时。","黄山白水空孤讽，叠嶂双溪属好诗。","击柝晓传邾子国，举鞭春到习家池。","只今霖雨思贤佐，会见丝纶下王墀。"]},{"t":"谢景高兄惠鱼蟹","f":"七言古诗","c":["霜风激水蟹舍寒，渔火献俘清夜阑。","不烹五鼎若赊死，使之骨醉尤加餐。","尺半之鱼鳞六六，同入糟丘随小牍。","鼎来兼味口流涎，可使盘中食无肉。","浔阳从事姿南金，高山调古谁知音。","宁同娵隅作蛮语，生憎郭索多躁心。","檐头雪消春有意，洗盏开尊宜一醉。","持螯颇忆左手同，尺素不妨时遣使。"]},{"t":"送唐左史纸墨","f":"七言古诗","c":["黄山奇峰三十六，耸壑寿松多节目。","真工曲突扫芳煤，介圭拱璧陈玄玉。","浙河千里兹滥觞，万谷之皮捣冰霜。","肌理细腻色白皙，蜀网剡藤难雁行。","使君来自岷峨麓，曾赋客卿朝奏牍。","细字不作蝇头书，高文富有牛腰轴。","向来平步第一螭，勇退宛在番之湄。","陶泓毛颖幸旅进，快写元和圣德诗。"]},{"t":"送李泉","f":"七言古诗","c":["周人九府有圜法，汉京金布在令甲。","炊炭冶镕多乱真，纷纷轻薄如榆荚。","即山不复私下臣，张官置吏几王春。","君子谓之阿堵物，方兄不知何许人。","十羊九牧其弊近，谈何容易趣销印。","事权顿使归民曹，鼓铸伊谁察诸郡。","诏书恳恳修废官，诸公争言隃度难。","向来矫枉亦太过，畴咨英俊乘輶轩。","鼎新能事推心计，贯朽不须夸古始。","共瞻使者振绣衣，曾见真人兴白水。","荀卿自有富国篇，高视管萧宜并肩。","钱流地上小小尔，便合论思雨露边。"]},{"t":"江州尘外亭","f":"七言律诗","c":["使君人物风尘表，亭下纤埃远白蘋。","佳传缅怀方外友，漫郎端是社中人。","山光水色长排闼，鹄侣鸿俦已卜邻。","莫语软红车马客，香炉峰下有遗民。"]},{"t":"喜景徐作小圃因怀东阁二绝句 其一","f":"七言绝句","c":["数顷澄湖练有光，小亭处处得疏篁。","梦中春草多佳句，一洗尘埃速寄将。"]},{"t":"喜景徐作小圃因怀东阁二绝句 其二","f":"七言绝句","c":["白白朱朱手自栽，两年忆著满林开。","莫教童稚轻攀折，惜取浓阴待我来。"]},{"t":"次韵董伯鲁","f":"七言律诗","c":["读破群书有远谋，逢时便可动凝旒。","不辞岩邑千山险，肯作铃斋十日留。","辩舌未容蠡测海，归心已梦蝶为周。","松关万一逢佳友，为说相如故倦游。"]},{"t":"端午日应贤小集戏用坐中语","f":"七言律诗","c":["短檠长忆桂岩东，翰墨新来莫论功。","日日簿书成俗吏，星星鬓发逼衰翁。","公祠难缓三人带，小垒聊吟一马骢。","共饮昌蒲修故事，山肴野蔌是家风。"]},{"t":"次韵黄子馀惠双井茶二首 其一","f":"七言律诗","c":["荻花枫叶醉为乡，每忆临分一鼎香。","枉费光阴惊老大，略无治行愧循良。","归心来往鸡豚社，清思消磨雁鹜行。","且喜弦歌馀乐地，好诗句句挟风霜。"]},{"t":"次韵黄子馀惠双井茶二首 其二","f":"七言律诗","c":["峰横万仞临双井，调护旗枪春怕深。","白雪有芽鹰作爪，黄粱无梦蝶何心。","闻名可信非虚语，知味端如赏好音。","祇欠谷廉一杯水，末能相就盍朋簪。"]},{"t":"送范至能","f":"五言古诗","c":["愁云暗千山，欲雪意未歇。","雨脚侵夜分，鹢首勇朝发。","软红英俊林，定不冗干谒。","磊落胸中书，高谈倾上笏。","结驷映天街，登瀛有仙骨。","摩挲先友碑，姓名或湮没。","却顾浮丘亭，寄声频日月。"]},{"t":"次韵王伟文二首 其一","f":"七言律诗","c":["山城碌碌负鱼符，尺五家园好坦途。","可惜光阴迷簿领，漫无惠露到樵苏。","鸡豚小社元相接，鸥鹭新盟不敢渝。","莫话弹冠仍结绶，祇宜袯襫与夫须。"]},{"t":"次韵王伟文二首 其二","f":"七言律诗","c":["衒石难夸和氏场，挥犀久避盖公堂。","笔端风雨真无敌，纸上寒温细作行。","结屋竞传千亩竹，奉祠聊对一炉香。","朝中环赐无虚月，遥想眉黄已效祥。"]},{"t":"次韵程观过","f":"七言律诗","c":["山城寂寂簿书稀，梅际春风一夜归。","忽喜烹鱼中有得，恍然挥麈久相违。","折腰岂爱蕲州竹，问汉须寻织女机。","奇绝黄山待佳句，何时小雨湿征衣。"]},{"t":"和州","f":"五言律诗","c":["叹息和州事，腥膻未易除。","惊涛饮胡马，壮士葬江鱼。","列戍俱奔命，斯民不奠居。","元戎犹拥钺，资斧定何如。"]},{"t":"三将","f":"五言律诗","c":["鼎立淮南将，胡来竞退师。","折冲潜白羽，告捷闹黄旗。","已报瓜洲败，还惊采石危。","边防恃天堑，百万岂熊罴。"]},{"t":"胡虏","f":"五言律诗","c":["胡虏猖狂甚，妖星近日畿。","俄闻佛狸死，不得帝羓归。","虎旅空增灶，狼狐为解围。","人人说恢复，进退在投机。"]},{"t":"詹氏仁寿轩","f":"七言绝句","c":["修竹林林贯四时，厖眉扶杖到期颐。","子孙长忆当年事，留取轩楹客赋诗。"]},{"t":"道中怀景卢","f":"五言律诗","c":["宦路多睽别，春游隔弟兄。","频年再登陛，十日又离京。","吏责仓台少，官曹省闼清。","床头何夕月，冷话听残更。"]},{"t":"阐阳驿二绝句 其一","f":"七言绝句","c":["略略春晴天亦悭，雷惊雨作转头间。","浮云又逐东风起，不见前山出髻鬟。"]},{"t":"阐阳驿二绝句 其二","f":"七言绝句","c":["触石泉声高下闻，曾将两耳洗埃尘。","相逢尊酒今谁侣，细草青花是故人。"]},{"t":"次韵范守翠微亭","f":"七言律诗","c":["带郭长堤十里春，是中佳处外风尘。","层层危磴浑依旧，一一高亭已斩新。","领略江山初纵目，剪除荆棘不劳神。","携壶一笑须投隙，官事何时可脱身。"]},{"t":"次韵施德初游齐山","f":"七言律诗","c":["诗尘谁复数齐梁，小杜文章楚大邦。","曾为黄花酬九日，至今陈迹擅三江。","新亭高下依乔木，远岫参差进曲窗。","著屐与君时茗饮，后车何必酒盈缸。"]},{"t":"再赋","f":"七言律诗","c":["向来胡马远跳梁，奔命纷纷不一邦。","景物何期新斸壑，梦魂犹自怯防江。","看山小隐红莲幕，批敕须临青琐窗。","无事肯来文字饮，为将红酒倒鹅缸。"]},{"t":"喻江宁欲遗蕲笛辞之","f":"七言律诗","c":["蕲州美竹今古名，白云吹裂笛一声。","臞儒所对笔墨客，长物虚寻疏比僧。","还君不用君莫怪，绮窗办得千金买。","谁与移根到草堂，它日风来听天籁。"]},{"t":"烈士","f":"五言律诗","c":["烈士死知己，交情重同心。","反眼如不识，怨深恩更深。","忆昔邂逅初，一诺百黄金。","口血顾未乾，旧盟何许寻。"]},{"t":"景卢自右史假北门出疆再用前韵","f":"五言律诗","c":["汉节螭坳出，青毡映父兄。","天方摧丑虏，人已望神京。","使指今兹重，边尘定可清。","归来陈口伐，莲烛问严更。"]},{"t":"闻应贤景高文特少张景孙同客景卢官舍","f":"五言律诗","c":["使回亲旧集，虎穴问穹庐。","半夜枥喧马，高秋盘进鱼。","真成聚东井，谁复话南徐。","底事桃源客，新来书也疏。"]},{"t":"左举善求草堂诗","f":"七言绝句","c":["孤山佳处著茅庐，饱看云烟自卷舒。","莫向淮南恋戎幕，松关恐有绝交书。"]},{"t":"次韵景裴赞喜农扈之除","f":"七言律诗","c":["北固金焦顾眄中，裴回于此再踰冬。","徒劳金谷供诸将，未有田园问老农。","且喜边亭罢欧脱，不须水战习蒙冲。","九卿已愧班行忝，敢向明时叹不逢。"]},{"t":"答木缊之用前韵见寄","f":"七言律诗","c":["魁星秀句挟东风，便觉阳春变盛冬。","愧我供军侪绛灌，羡君汲古到羲农。","北邻再讲衣裳会，京口今为冠盖冲。","已具扁舟勇归去，粲花清论度难逢。"]},{"t":"得江楼","f":"五言律诗","c":["官事何时了，凭高思豁然。","逐江开北户，望岫顿修椽。","繁卉浑相亚，新篁便可怜。","归心入春梦，已绕故山前。"]},{"t":"花信亭","f":"五言律诗","c":["解报花消息，江边有好风。","吹香四时别，问讯几人同。","梅坞难藏白，桃蹊岂借红。","但能长检校，定不酒尊空。"]},{"t":"小雨同裴弟深甫坚上人登新亭次韵","f":"七言律诗","c":["移梅种竹趁阳春，举目江山发兴新。","曲槛疏窗那草草，飞檐碧瓦已鳞鳞。","鼎来好语酬佳景，更有高僧话净因。","步屧踌躇乌亦喜，不嫌风雨垫冠巾。"]},{"t":"春雪再作戏成绝句","f":"七言绝句","c":["常年穷腊无一白，盈尺冬来已屡书。","底事天公太手熟，又同春絮到阶除。"]},{"t":"寄题陈阜卿总秀堂","f":"五言律诗","c":["佳丽并包地，曼花子夜香。","望中团野色，尘外发天光。","小队高牙驻，轻裘清啸长。","故应堂上燕，相与贺雕梁。"]},{"t":"使虏道中次韵会亭","f":"五言律诗","c":["平野风烟阔，孤村父老存。","薄云低故堞，落日逐輶轩。","分裂时云久，澄清敌未吞。","春光满花柳，天道竟何言。"]},{"t":"过谷熟","f":"七言律诗","c":["玉帛齐盟亦可寻，东风著面客尘侵。","隋堤望远人烟少，汴水流乾辙迹深。","桃李不言应感旧，山川无主祇伤今。","遗民久厌腥膻苦，辟国谋乖负此心。"]},{"t":"次韵马上偶成","f":"七言律诗","c":["天遣祥风扫塞氛，越疆轺传礼仪新。","禦戎可鉴秦无策，觇国谁夸郑有人。","鸣鹤九皋闻彻响，翔龙千载仰攀鳞。","垂鞭日日陪清话，谈笑成章泣鬼神。"]},{"t":"次韵车中倦吟二首 其一","f":"七言绝句","c":["旧国于今作两家，邻翁有酒不能赊。","明朝又逐归鸿去，祇有尘埃满一车。"]},{"t":"次韵车中倦吟二首 其二","f":"七言绝句","c":["叱驭宁辞历险难，投戈且幸迩遐安。","毡车轩簸长危坐，恰似舟行八节滩。"]},{"t":"次韵初入东京二首 其一","f":"七言绝句","c":["乾坤正欲稔天骄，会见降胡款圣朝。","蓄锐乘机先自治，莫令武库五兵销。"]},{"t":"次韵初入东京二首 其二","f":"七言绝句","c":["五门双阙未央城，碧瓦朱甍云雾生。","真主南巡正尝胆，从今瞻仰泰阶平。"]},{"t":"过黄河用上介龙深甫迁居旧韵","f":"七言律诗","c":["风埃如雾满川黄，马上朝来识太行。","水泻浊河桥甚壮，沙连远塞路何长。","皇华复讲衣裳会，京阙今为毡罽乡。","夹道桑麻过千亩，野花时有一枝香。"]},{"t":"绝句","f":"七言绝句","c":["宣防瓠子挠西京，向者河堤役不宁。","胡虏任教流就下，始知谈舌误朝廷。"]},{"t":"次韵北使邀观常丰湖","f":"七言绝句","c":["一派澄湖何处来，鸣桹渔子聚还开。","主人甚顾他乡客，莫使归途欠一杯。"]},{"t":"次韵初望太行山","f":"五言律诗","c":["曾峦逾碣石，形胜镇神州。","可惜羊肠险，今包鼠穴羞。","天心端有待，人力岂能谋。","未老如凭轼，壶浆为曲留。"]},{"t":"次韵伊洛道中","f":"五言律诗","c":["万里修邻好，毡裘不乱群。","边锋方两解，春事已平分。","发轫鸡三唱，挥毫酒半醺。","问途殊未已，返顾羡归云。"]},{"t":"次韵汤阴寒食遇雨","f":"五言律诗","c":["殊方遇寒食，节物负年华。","小雨偏宜柳，轻风未落花。","见饧如隔岭，对月共忘家。","俗重之推庙，谁祠万里沙。"]},{"t":"次韵讲武城","f":"七言律诗","c":["汉鼎三分霸业成，并吞犹未戒佳兵。","故城四壁存陈迹，荒冢千年断乐声。","何必枕戈防诡计，岂容横槊窃诗名。","我来吊古停车辙，垄上农人也辍耕。"]},{"t":"次韵赵州石桥","f":"五言律诗","c":["访古汶河上，聊忘道路劳。","仙踪尝策蹇，海怪或镌鳌。","济远徒杠小，凭虚乱石牢。","何时冠盖集，一变犬羊臊。"]},{"t":"过中山","f":"五言律诗","c":["三关标重镇，自昔护边陲。","观者堵墙立，纷然帘幕垂。","欲谋千日醉，恐误十旬期。","可喜中庭月，何妨尽一卮。"]},{"t":"过保州","f":"五言律诗","c":["艺祖枌榆社，唐人保塞军。","百年邻毳幕，今日聚妖氛。","故老垂黄发，妍姬艳綵裙。","白沟才一舍，何计可中分。"]},{"t":"次韵早行","f":"五言律诗","c":["夙驾星光动，徐行雾气迷。","塞鸿翻月去，胡马向风嘶。","柝静谯门晓，轮攲沙路低。","颇思眠蕙帐，枕上听邻鸡。"]},{"t":"次韵得保州老张瓦研","f":"五言古诗","c":["毛颖传既成，陶泓名不朽。","陈楮接武来，论交篇籍囿。","千年铜雀台，瓦解沦坤厚。","何人澄其泥，颇能髣髴否。","龙公天上客，金兰幸同臭。","结束万里行，联翩五旬久。","清谈落玉麈，痛饮尽金斗。","咳唾珠玑粲，挥翰不停手。","穷边得佳研，可出老吕右。","瓦缶莫雷鸣，龙尾羞牛后。"]},{"t":"次韵保州闻角 其一","f":"七言绝句","c":["觉来屈指数修程，历遍中原长短亭。","谁向城头晓鸣角，胡音嘈囋不须听。"]},{"t":"次韵保州闻角 其二","f":"七言绝句","c":["胡音嘈囋不须听，整顿征衫待启明。","已把哀笳变清角，可伤任昧杂韶英。"]},{"t":"次韵梁门","f":"七言绝句","c":["双垒依然柳作阴，故疆行尽倍伤心。","时平且得无争战，苔上戈枪卧绿沈。"]},{"t":"次韵白沟河","f":"七言绝句","c":["唐馀画壤愧鸿沟，西闭关门汉道柔。","一自旄头入京洛，至今泉水不东流。"]},{"t":"次韵回程至涿鹿","f":"七言律诗","c":["回首燕然日再西，一杯相属使轺归。","残花媚野不妨好，倦鸟投林自在飞。","可惜光阴销客枕，不嫌尘土染征衣。","大明退直清和日，已约梯云访翠微。"]},{"t":"燕馆日膳得四雁笼之以归","f":"七言绝句","c":["提携乘雁脱庖丁，等待他年羽翼成。","唳月摩云须有便，莫教更作不能鸣。"]},{"t":"次韵杨花二首 其一","f":"七言绝句","c":["桃花开落不同时，燕子衔泥相伴飞。","若向章台问春色，可无清泪湿征衣。"]},{"t":"次韵杨花二首 其二","f":"七言绝句","c":["官路风轻落絮迷，望中高下杂游丝。","糁毡拟雪春无际，只有骚人圣得知。"]},{"t":"再至保州","f":"五言律诗","c":["再入中原境，相迎有暮鸦。","柔桑新迸叶，高柳细吹花。","短帻人如秃，尖冠女不髽。","指期淮可渡，宁叹在天涯。"]},{"t":"次韵再至中山","f":"五言律诗","c":["路指中山国，人归析木津。","终风震檐瓦，细雨压车尘。","落纸诗章速，开尊酒力醇。","无功惭报国，来往谩劳人。"]},{"t":"次韵中山雨后","f":"七言律诗","c":["好雨连宵鸠唤晴，晓行襟袂有馀清。","远游朔塞殊风景，梦到东阡看火耕。","红退桃蹊三月晚，绿添麦垄一川平。","纤尘不逐车轮起，喜听驱驴叱马声。"]},{"t":"次韵村店得牡丹","f":"七言绝句","c":["花品称王擅洛京，朱朱白白莫齐名。","相逢河朔春将暮，半吐檀心若有情。"]},{"t":"次韵陈留闻莺","f":"七言绝句","c":["恰恰啼莺马上听，凝云欲雨晓寒轻。","满郊碧草皆春色，祇欠山光与水声。"]},{"t":"次韵宁陵憩驿","f":"五言律诗","c":["野外人声寂，林间鸟羽翻。","朱樱喜堆案，青杏助开尊。","故国多荒草，遗黎有怨言。","雨馀尘土静，不复污归轩。"]},{"t":"次韵南京道中","f":"七言律诗","c":["密叶成阴行路宽，鸠鸣莺啭足开颜。","半涂泥滑夜来雨，数片云飞何处山。","薄暮每寻樽俎共，残春能伴节旄还。","尘襟好濯西湖水，偷取禅房一日闲。"]},{"t":"次韵游臞庵不果","f":"七言律诗","c":["水纹如縠送归船，渐近觚棱尺五天。","适意莼鲈公有兴，寻盟鸥鸟我无缘。","远怀并辔穿红皱，近阻携筇款碧鲜。","却待湖山最高处，醉中一笑挹臞仙。"]},{"t":"寄别景卢","f":"七言律诗","c":["禹穴遗书不可寻，坐看绿叶再成林。","千岩竞秀非吾土，三径就荒劳我心。","谁是周人思召伯，今无老叟出山阴。","台阶稳上添花萼，时倩来鸿续好音。"]},{"t":"蓝宪遣人往吴门移洛花未至而去 其一","f":"七言绝句","c":["雒京隔绝花难得，茂苑移将信已通。","世事好乖犹献鹄，雕栏不用怨东风。"]},{"t":"蓝宪遣人往吴门移洛花未至而去 其二","f":"七言绝句","c":["新坛巧斲列东西，准拟看花倒接篱。","交臂失之端可笑，傥来外物尽难期。"]},{"t":"蓝宪遣人往吴门移洛花未至而去 其三","f":"七言绝句","c":["三春桃李家家有，不费阳和特地恩。","名品异芳天亦靳，未教容易到丘园。"]},{"t":"登芝榭见景卢所增月台","f":"七言律诗","c":["台榭相望闻语声，茹芝观月有馀清。","旁连小隐分三径，细数修篁限一城。","日日杖头思径醉，年年铛脚玩欣荣。","谁人知我归欤乐，趁此登临未惮行。"]},{"t":"许倩报白榴已得玉茗未谐以诗趣之","f":"七言律诗","c":["万里移根安石国，何年傅粉未知名。","须邀玉茗来岩壑，便结琼花作弟兄。","诗客定疑天外得，园人已办腊前迎。","东家阿措休相妒，不学秾妆照眼明。"]},{"t":"次韵景卢喜得安州牡丹","f":"七言律诗","c":["洛中花信已沉声，泾渭宁分浊与清。","近出黟山空接壤，远来安陆比连城。","虚坛仅免游人问，浪蕊从教著处荣。","更欲丁宁新芍药，莫誇多少便横行。"]},{"t":"次韵景卢野处解嘲之什","f":"七言律诗","c":["地偏不接市廛声，古木参天鹤唳清。","台榭迥穷千里目，诗章突过五言城。","花移琼树真无敌，酒换金貂未足荣。","灯火归时笙管作，解嘲何事有歌行。"]},{"t":"再赋","f":"七言律诗","c":["幽壑藏云水作声，纫兰入室好风清。","高蜚便有缥缥意，进筑如开荡荡城。","百尺楼成同日涉，四时花发匪朝荣。","园池如许谁言小，但放刍荛雉兔行。"]},{"t":"酬景卢赋圃中种橘移花","f":"七言律诗","c":["瓮头玉友已销声，小试山斋百末清。","十客对花休避席，千奴呼橘拟专城。","微霜到处叶未落，小雨移来根易荣。","情话团栾亦终日，坐中惟欠十般行。"]},{"t":"酬景卢谢菊","f":"七言律诗","c":["涉秋无复滴阶声，夜雨随风尘已清。","平日爱山营一壑，老来学圃列三城。","园夫种树元无术，篱菊分丛独晚荣。","蹑屐问花兼问柳，不须乘毳可泥行。"]},{"t":"答景卢","f":"七言律诗","c":["雁翅齐飞有隽声，文章何止赋华清。","谁教短策长寻壑，不拥高牙且典城。","台省向来非独冷，身名此日已俱荣。","盈旬诗轴牛腰大，抱牍须同饕虱行。"]},{"t":"病酒","f":"七言律诗","c":["三日惟闻煮药声，一中可怕圣之清。","移花种竹已得地，逢酒当歌须闭城。","远避霜风严北户，静看朝日满东荣。","双螯退步输年少，谁与抽琴作蟹行。"]},{"t":"答景严","f":"七言律诗","c":["向来戎马沸边声，曾出良筹助扫清。","六载倦游潜楚泽，一枝同折记栾城。","北门西府仍班缀，后雁前鸿愧宠荣。","两鬓星星吾老矣，看君重上赤墀行。"]},{"t":"景严送冬杏","f":"七言律诗","c":["苍头呼梦杂鸡声，蕊杏诗来句转清。","独傲风霜爱冬日，不随桃李媚花城。","一枝得得能相对，凡卉纷纷孰并荣。","大队开时春且尽，醉吟当续丽人行。"]},{"t":"景卢送瑞香","f":"七言律诗","c":["翠幄藏春巧寄声，熏笼织锦晓天清。","幽香端是花中瑞，仙派初来尘外城。","酒海何妨三雅进，鬓云谁称一枝荣。","雨来顿使邻墙远，不到阑干深处行。"]},{"t":"野处有诗羡山居小隐之广而有拓地不可之叹","f":"七言律诗","c":["败叶翻风策策声，山根可掬石泉清。","东邻美荈久成坞，北陌新柑小筑城。","台在家边来更好，地连郭外得非荣。","曾楼纵目无穷景，安用垂涎杖屦行。"]},{"t":"再赋","f":"七言律诗","c":["厌听朱弦裂帛声，携锄斸壑赋临清。","赏心尽得难并景，舒足休嫌踏破城。","夜璧朝琼宁独乐，春兰秋菊岂争荣。","闭关不使高轩过，只许渔樵为辅行。"]},{"t":"忆城东来禽","f":"七言绝句","c":["远送来禽我独无，后来才得两三株。","隐园野处花难比，祇恐人评棣萼图。"]},{"t":"忆古城柿","f":"七言绝句","c":["果园幽僻少能知，丹柿乌椑手自移。","欲学郑虔书坠叶，何人解有寄来时。"]},{"t":"忆隆庭竹","f":"七言绝句","c":["闻道隆庭竹满园，许分苍翠长儿孙。","看看冬尽无消息，始信壮周是寓言。"]},{"t":"忆吴中洛花","f":"七言绝句","c":["书邮浸失鳞鸿约，栏槛长教蜂蝶猜。","待拟子虚乌有赋，东宾仍遣耳孙来。"]},{"t":"戏孙陈二弟 其一","f":"七言绝句","c":["城东卜筑有期无，须为檐楹动百株。","可忍非时归爨下，合尖何似助浮图。"]},{"t":"戏孙陈二弟 其二","f":"七言绝句","c":["古城栽种畏人知，定是根盘不可移。","车载斗量稗贩走，果纲却有入州时。"]},{"t":"戏孙陈二弟 其三","f":"七言绝句","c":["傍巘经营杂果园，翻愁它日逐王孙。","不如种竹招风月，此意难逢俗子言。"]},{"t":"戏孙陈二弟 其四","f":"七言绝句","c":["林居草创名花少，柳径苔生过客猜。","不管空言无实惠，只嫌巧取近嗟来。"]},{"t":"再赋 其一","f":"七言绝句","c":["外求它壤曾攀桂，近舍家园尚守株。","待得枝头如赤柰，却来看我百花图。"]},{"t":"再赋 其二","f":"七言绝句","c":["圃在前村若个知，山逢愚叟会须移。","前言戏耳君休怪，七绝成阴自有时。"]},{"t":"再赋 其三","f":"七言绝句","c":["何人种柳成门巷，几处看花到子孙。","且尽山斋一杯酒，此君相对已忘言。"]},{"t":"再赋 其四","f":"七言绝句","c":["长惭无地起楼台，觅果寻花颇受猜。","且向园林聊寓意，不教丝管逐人来。"]},{"t":"送景卢","f":"七言律诗","c":["涉世难防犬吠声，放怀安可俟河清。","昂霄莫辨千寻木，凿牖聊看三里城。","丹橘黄甘随处好，美花香草逐时荣。","晚来寒雨催归骑，酷似邹人接淅行。"]},{"t":"送朱叔召归吴中","f":"七言律诗","c":["长忆吴中鸣橹声，风高月上水波清。","臞庵掩映花成聚，笠泽微茫烟若城。","十载相忘存梦想，一帆此去喜归荣。","老来无复莼鲈会，尚看骅骝得路行。"]},{"t":"景孙以妇病稽赏甘尝蟹之约景卢以诗诘之","f":"七言律诗","c":["郑庄好客底虚声，药裹关心兴未清。","应恐被围因鲁酒，也防完璧弃秦城。","双螯弗讲连宵会，千橘谁教满路荣。","见说高台新断手，何如自索玉杯行。"]},{"t":"戏景卢","f":"七言律诗","c":["千橘亭前莫听声，岂无邺酌和汾清。","轻裾长袖闲列屋，碧瓦朱甍高照城。","台上金波催夜集，楼边玉树待春荣。","赏花斫鲙言犹在，还被题舆诮却行。"]},{"t":"隆庭竹至四绝句 其一","f":"七言绝句","c":["忆昨分抄种树书，三荆今古美同株。","闲将草木供诗戏，待把渔樵足画图。"]},{"t":"隆庭竹至四绝句 其二","f":"七言绝句","c":["竹里巧传幽鸟语，月台高视客星移。","乡园何幸立分鼎，鸣鼓铿钟乐圣时。"]},{"t":"隆庭竹至四绝句 其三","f":"七言绝句","c":["斑箨远移湘岸种，猫头亦是渭川孙。","百金得诺今无恨，千亩封侯不在言。"]},{"t":"隆庭竹至四绝句 其四","f":"七言绝句","c":["装景松篁浑可喜，忘机鸥鹭不相猜。","南窗情话有时尽，唤取青州从事来。"]},{"t":"答景卢久阴遣闷","f":"七言律诗","c":["几日思君环佩声，方冬天宇未澄清。","冲寒也到临春阁，处暗如登却月城。","整顿建瓴愁雨作，商量设醴卜花荣。","锦囊不用诗排闷，起看朝云亦倦行。"]},{"t":"喜小隐新得山茶","f":"七言律诗","c":["芳园封植阅年华，异卉搜求闹小车。","不羡竹林生石竹，独来茶坞补山茶。","游人认柿枝头子，归鹤求雌叶底花。","我去临川寻玉茗，遥将白雪映红霞。"]},{"t":"答小隐惠山茶","f":"七言律诗","c":["何处仙官萼绿华，鞭鸾独御五云车。","来从月窟曾依桂，分种盘洲不碍茶。","枝耐岁寒犀换叶，蕊藏朝雾锦羞花。","红颜不逐东君老，须著频来斗脸霞。"]},{"t":"答小隐闻野处开尊","f":"七言律诗","c":["遗我双鱼集棣华，尚疑信马误随车。","丝声自是不如肉，酒薄须知大胜茶。","翠袖明朝看倚竹，兰灯昨夜报开花。","饮阑同步曾台月，古堞危亭见绮霞。"]},{"t":"答小隐喜得白山茶之报","f":"七言律诗","c":["素质宁嫌潘鬓华，来时应有雪翻车。","赋传山谷文堆绣，种出麻源韵胜茶。","不向桂宫藏玉兔，合横蕊观俪琼花。","冥搜未获诗先作，驻目轻帆溯落霞。"]},{"t":"忆东阁手植花木用雍陶过旧宅看花诗韵","f":"七言绝句","c":["分根徙核望春栽，曲径幽蹊手自开。","今日成林浑著子，花时不折一枝来。"]},{"t":"玉茗未有耗而小隐作诗以琼花为二绝当专美野处可也","f":"七言律诗","c":["休论官业出金华，共乐家林鹿挽车。","何日寻春携漉酒，有时留客试擂茶。","望梅止渴宁非梦，却月横枝始是花。","祇恐偏枯惭好句，空教步障锦如霞。"]},{"t":"和景严送方蒂柿","f":"七言律诗","c":["万株红叶咏光华，嘉实堆盘走绀车。","方蒂宁同牛奶柿，朱唇应笑鸠盘茶。","园官急送须足茧，童子争观多眼花。","罗列林珍生饮兴，讵思辟谷更餐霞。"]},{"t":"答景卢怀旧","f":"七言律诗","c":["了无梦寐到京华，来往园林整钓车。","缓步竞移霜后橘，清谈旋碾雨前茶。","虚名长愧称三凤，旧事休怀判五花。","共把诗筒销永日，喜君襟韵秀朱霞。"]},{"t":"园中观种树","f":"七言律诗","c":["望中赤叶渍霜华，林下徐行便当车。","好处见山仍见水，兴来呼酒不呼茶。","旋移朱橘添卢橘，更拣红花间白花。","出郭最欣尘事少，饱看孤鹜逐飞霞。"]},{"t":"答景卢报月台将毕工","f":"七言律诗","c":["新筑崇台款桂华，凌虚如跨白鸾车。","西瓜来自余吾水，远物谁询悉里茶。","不减平泉书草木，更寻南部录烟花。","落成有约何时讲，舞袖还看举彩霞。"]},{"t":"答景严咏山居夹道种松","f":"七言律诗","c":["投黻归来发半华，苍官怪我出无车。","树当樵径频争席，地接禅房好觅茶。","要使行人长荫樾，不教侍女独司花。","十园五鬣它年事，会见摩空薄绛霞。"]},{"t":"和景卢饯朱叔召往宣城","f":"七言律诗","c":["与客窥园春未华，也须日昃始回车。","松间共赏猫头竹，酒半先尝雀舌茶。","云覆疏棂香起篆，风侵密坐烛吹花。","双溪叠嶂催行色，佳句重吟绮散霞。"]},{"t":"答景卢咏道上新松","f":"七言律诗","c":["落落乔松说九华，远移霜骨想专车。","沦脂此地能和药，结实殊方却入茶。","村女拾钗分翠叶，野人敲粉聚黄花。","翛然一径穷芝岭，晓见飞云夕见霞。"]},{"t":"和景卢雨中叹","f":"七言律诗","c":["工徒滞雨望朝华，好倩泥蛮指日车。","末利怯寒先近火，瑞香蒙润免浇茶。","莫嫌云暗青油幕，尚恐天开端木花。","待得严霜变阴翳，便须酌酒赏金霞。"]},{"t":"和景卢喜晴","f":"七言律诗","c":["共喜胡尘不乱华，戍边聊出武刚车。","天公欲遣风催雪，僧舍方疑烟湿茶。","巡圃观橙无坠叶，隔溪移杏恐伤花。","举头忽见云间日，急草诗章庆半霞。"]},{"t":"闽商货千叶牡丹疑其非而却之并怀蓝宪所许","f":"七言律诗","c":["星文陨石应皇华，鹊语参差雨洗车。","忽报商人缄苇箧，初疑闽产杂官茶。","栽培况乃三冬月，真赝难分千叶花。","宁使双坛且虚左，空吟轻日护香霞。"]},{"t":"和景卢咏新得歙县牡丹","f":"七言律诗","c":["旁搜嘉卉对韶华，宝玩明珠诧照车。","可使东坛无蔓草，如游北苑得名茶。","安排酿具多炊黍，准拟襟期共赏花。","醉语美人无可恨，不教拖帔泣归霞。"]},{"t":"野处送百结花","f":"五言律诗","c":["盘屈枝仍垫，葱青叶未稀。","双衔疑凤带，百结类鹑衣。","弱骨长连锁，轻腰孰解围。","若教花自在，应作彩云飞。"]},{"t":"野处送金灯花","f":"七言绝句","c":["银灯未茁有金灯，翠叶森森比剑棱。","待得花光无断续，却须拈出问邻僧。"]},{"t":"和景严咏冬开木犀","f":"五言律诗","c":["桂枝冬更好，浪蕊到今稀。","雅韵催吟笔，幽香傍舞衣。","月分千里影，风突百花围。","倚策山亭暮，寒鸦亦倦飞。"]},{"t":"和景严约赏木犀","f":"五言律诗","c":["蔌蔌蟾宫桂，冬开自昔稀。","犀通一点骨，蜜染六铢衣。","樽渌拚深酌，炉红渐可围。","赏花宜卜昼，莫待晚霞飞。"]},{"t":"喜景卢有落成琼楼之约","f":"五言律诗","c":["地近篮舆便，心清俗事稀。","檐花琼结佩，窗月练垂衣。","松竹添三径，溪山豁四围。","落成歌管集，仰首暗尘飞。"]},{"t":"和景严咏新得蒲萄","f":"五言律诗","c":["名传马乳久，物比蚌胎稀。","高出酴醾架，轻铺薜荔衣。","孤根临水窟，疏蔓接篱围。","急酿凉州酒，西园盖欲飞。"]},{"t":"得洛中牡丹","f":"五言律诗","c":["洛花天下选，千里凑三园。","望岫方缄恨，凭莺忽践言。","群葩俱退舍，胜日便开尊。","莫惜诗偿债，真同香返魂。"]},{"t":"蓝宪所送牡丹道远失时颇多枯槁","f":"五言律诗","c":["殷勤人有信，惊喜得花饶。","可惜三冬晚，来从千里遥。","根荄愆润泽，牙檗顿枯焦。","傥有更生路，宁辞楚些招。"]},{"t":"答景韦赴调还家见寄","f":"七言律诗","c":["迎归乌鹊竟传声，摆落埃尘襟宇清。","薪桂岂容留帝阙，幕莲且得近乡城。","眼边触处梅争破，陌上分行柳向荣。","如约速来春可探，肩舆须去静中行。"]},{"t":"许倩遣舟送花栽","f":"七言律诗","c":["双舟十日涉长湖，瓷斛筠篮且百株。","可喜石榴初变白，更惊玉茗不施朱。","临风含笑劳花使，映水分行拥木奴。","装点园林娱杖屦，好来一醉倒金壶。"]},{"t":"予得圃芝山之麓去春始治畦径名曰山居中为芝榭四楹其秋双芝产于榭南今夏复见四本而盘洲亦有其二因刻诗以志之","f":"七言律诗","c":["山中曾有采芝仙，此日灵根讵偶然。","题柱漫将诗纪实，凭栏真共酒忘年。","英华可是丘园瑞，造化元非雨露偏。","留与山居作嘉话，未甘草木羡平泉。"]},{"t":"双溪堂","f":"五言律诗","c":["负郭藏嘉处，清溪夹岸流。","风漪前后起，云态浅深浮。","入户松横岫，开窗橘满洲。","心闲身自在，尘事底能留。"]},{"t":"舣斋二绝句 其一","f":"七言绝句","c":["野色山光列画图，坐看渔子入菰蒲。","恰如放鹢穿三峡，何事航家问五湖。"]},{"t":"舣斋二绝句 其二","f":"七言绝句","c":["青翰不动柳阴多，桂棹无声鸟语和。","有此孤舟寄丘壑，可怜平地起风波。"]},{"t":"侣鸥亭","f":"五言律诗","c":["憩策新亭上，波光入坐来。","鱼游能自乐，鸥狎肯相陪。","风快尘襟豁，云深俗驾回。","寻盟须日涉，未怕落霞催。"]},{"t":"小隐芝草","f":"七言律诗","c":["芝丛盈百见闻希，不数嘉禾连理枝。","紫盖堆云光点染，金茎蒙露色凝脂。","一时竞秀园林胜，十载深藏天地知。","急办轩楹尊瑞物，泥封诏墨有来期。"]},{"t":"招二弟赏盘洲双头莲","f":"七言绝句","c":["何须艳质斗鲜妆，并蒂红蕖本自双。","却恐花飞成造次，急来相就倒银缸。"]},{"t":"紫薇花以六月至自溧阳在道已五十日今有花满树因示二弟","f":"七言绝句","c":["六月炎天千里移，不期繁蕊便盈枝。","向来浑是西垣客，忆得看花草制时。"]},{"t":"九日欲为云松之集以病倦而辍","f":"五言律诗","c":["半秋翻药裹，九日负云松。","黄菊从他好，清尊不我容。","零丁怜败叶，旁午羡游蜂。","今古登临恨，云迷五老峰。"]},{"t":"景卢约赏朝天菊不克往","f":"五言律诗","c":["暮节真无分，头风祇自知。","朝天虽有菊，向日不如葵。","久旱千株槁，深秋百草萎。","吾衰亦相类，饮兴谢东篱。"]},{"t":"除夕","f":"五言律诗","c":["岁尽春虽浅，更长夜亦阑。","枕边鸡送晓，窗外雁冲寒。","学圃心常在，筹边力所难。","老来惊节序，那复问椒盘。"]},{"t":"观园人接花","f":"五言律诗","c":["植杖看园吏，挥斤接果栽。","夺胎移造化，类我借根荄。","一似雀为蛤，能令桃作梅。","天工待人力，信手便春来。"]},{"t":"开岁三日有夜雨屡闻雷声继以大风晨起飞雪已盈积景卢作诗即事次其韵","f":"七言律诗","c":["旱灾已叹失秋成，春到谁教夏令行。","风阵骤来收雨脚，雪花未集听雷声。","阴阳改变才俄顷，冷暖乘除若晦明。","待向斜川会邻曲，占晴须问蜀君平。"]},{"t":"雪后游盘洲","f":"七言律诗","c":["书事斜川日月同，行年过四逼衰翁。","纵情自洗和陶笔，乘兴谁开访戴蓬。","梅萼仅存难聚雪，竹根未稳不禁风。","莫将野趣逢人说，冰上轻鸥西复东。"]},{"t":"舣斋观耕","f":"七言律诗","c":["城下经营二顷田，倒囊不惜买山钱。","一犁驻目雨初歇，三径藏身地自偏。","乞米帖来须领略，相牛经在与周旋。","尝新指拟翻匙雪，旱魃诛夷胜去年。"]},{"t":"景卢新治西园而亭榭未立以诗趣之","f":"七言绝句","c":["斩新曲径治西园，野色春来已可观。","便好作亭供客醉，望中流水有时乾。"]},{"t":"答景卢和篇","f":"七言律诗","c":["致君无术合归田，谁敢贪荣食万钱。","且对清尊希北海，最欣别墅接西偏。","转头麦垄龙工往，缓步花蹊蚁磨旋。","辛苦三农营一饱，莫教牟贼坏丰年。"]},{"t":"上元日圃中归","f":"五言律诗","c":["春风环柳岸，夜雨失沙痕。","环竹期新笋，移花护旧根。","身闲贪独乐，舌在戒多言。","是处无灯火，荒凉一上元。"]},{"t":"次韵梁宪盘洲之集","f":"七言律诗","c":["轻风吹雨称行春，丘壑装怀我辈人。","照水轩窗如进艇，穿花旌节屡移轮。","携壶迭讲三杯酒，挥麈曾无一点尘。","明日兵厨寻故事，已教园吏拂华茵。"]},{"t":"再和","f":"七言律诗","c":["于越归来三见春，买山学圃狎渔人。","非嫌厚禄轻捐印，所畏空餐咏伐轮。","时运可惊如过隙，人生何苦不同尘。","明年此会谁重讲，唯把书邮问鼎茵。"]},{"t":"江守置酒盘洲张贰卿两宪及景卢同集时江新兼泉司","f":"七言律诗","c":["皇华分鼎坐添春，隐雾巢松三散人。","半月阴云浓似墨，今朝晴日大于轮。","不辞多酌娱浮蚁，何用清歌落暗尘。","归去池塘入新梦，句中芳草醉中茵。"]},{"t":"再赋","f":"七言律诗","c":["到处争持曲米春，阗阗花底凑游人。","同盟非是新倾盖，巧匠谁云老斲轮。","倚竹岂无人拾翠，凌波谁想袜生尘。","后期直待荷花发，欲唤轻裾上舞茵。"]},{"t":"醉中三用韵","f":"七言律诗","c":["小车追逐赏光春，花坞行盘走隶人。","水面落英如濯锦，云心初月未安轮。","今宵同举盈觞酒，后夜还凝满席尘。","倒载归时童稚舞，莫教驺哄滓冯茵。"]},{"t":"雨中排闷","f":"七言律诗","c":["生怕花飞减却春，半旬苦雨恼幽人。","山房挂壁有双屐，村径冲泥无只轮。","但见渌波侵碧草，不须皂荚去黄尘。","拥炉更甚三冬月，转觉寒威逼坐茵。"]},{"t":"次韵梁宪再集盘洲","f":"七言律诗","c":["春风步屧共优游，小筑园庐匪拙谋。","罗列清尊资啸傲，安排好语待赓酬。","茸茸香草装三径，恰恰鸣禽想十洲。","玉节寻盟端不再，便回天上近凝旒。"]},{"t":"浮杯","f":"七言律诗","c":["南北芝泉一涧开，穿花度柳势萦回。","不须元巳方修禊，才遇良辰便泛杯。","行止岂由人智巧，沉浮长与客惊猜。","急流一去谁难进，却有先游殿后来。"]},{"t":"送吴远泽赴南宫","f":"七言绝句","c":["文压秋闱揽桂华，一鸣天陛稳乘槎。","归来须踏盘洲路，要看荷衣醉藕花。"]},{"t":"九曲有感","f":"五言绝句","c":["忽忽光阴转，骎骎华发添。","迹陈三可叹，心赏四难兼。"]},{"t":"岁三日插柳","f":"七言绝句","c":["欲教垂柳匝池台，寻觅长柯处处栽。","待得成阴身益老，攀条能有几番来。"]},{"t":"次韵梁子正咏棕亭","f":"七言律诗","c":["鬋得栟榈制数椽，绣衣拈出少陵篇。","倚楹见水幽情畅，驻屐迷花诗兴牵。","便觉茅轩俱退舍，若谈竹室不同年。","满山所欠青青药，且趁流觞集醉仙。"]},{"t":"梁子正有诗谢牡丹及聚仙花次其韵 其一","f":"七言绝句","c":["天教国色傲春华，不肯争先伍杂花。","西洛尘埃长太息，名园今属犬羊家。"]},{"t":"梁子正有诗谢牡丹及聚仙花次其韵 其二","f":"七言绝句","c":["痴坐林间类守株，一年春事已无馀。","直须九曲添清涨，洒扫棕亭进一盂。"]},{"t":"梁子正有诗谢牡丹及聚仙花次其韵 其三","f":"七言绝句","c":["玉蕊茸茸映四筵，团栾如集饮中仙。","下方簇蝶非俦匹，上比琼花难并缘。"]},{"t":"病中忆九曲","f":"七言律诗","c":["新穿九曲望时霖，水到渠成病已侵。","见说小舟穿柳岸，那知清涨入桃林。","五旬药裹长经眼，几日荷花复赏心。","梦里亦知行乐处，老来尤更惜光阴。"]},{"t":"六月乡城不雨祷赛无应得建康书一雨连半月至以望日丐晴感而有作","f":"五言律诗","c":["苍苍太手熟，岁岁厄吾乡。","千里均州县，三旬殊雨旸。","谁云不私覆，乃尔分此疆。","遂令远游子，转盼生炎凉。"]},{"t":"江鸣玉遗苍梧二苍鹤其一病两日而死陆鲁望诗云医鹤自须监吾乡人医尚无良手况禽医乎","f":"七言绝句","c":["病骨摧颓警露难，草埋长胫委苍翰。","吾乡尚欠肱三折，况有禽医为一看。"]},{"t":"八月下旬观邸报二绝句 其一","f":"五言绝句","c":["黄卷漫穷年，天梯欲上难。","闾阎听小子，竞欲裂儒冠。"]},{"t":"八月下旬观邸报二绝句 其二","f":"五言绝句","c":["叹息东坡老，聪明误一生。","不须多识字，捷径自横行。"]},{"t":"婺源乃歙之剧邑素有汤鼎之谤顷治此郡俾邑官作止沸之亭而不果吾宗应贤下车而风俗易书来求扁因为赋诗","f":"七言绝句","c":["琴堂少值烹鲜手，壮县空遭沸鼎名。","止火绝薪俱下策，风移全在长官清。"]},{"t":"宗人应贤婺源张氏之婿也治邑清介一无所私其列岳诒书郡幕至以邑尊称之其里谚如此戏成绝句","f":"五言绝句","c":["自昔为门婿，于今是邑尊。","秋毫无假借，情话与谁论。"]},{"t":"朱叔召遗文官花二绝句 其一","f":"七言绝句","c":["幻出荷衣点雪衣，更将龟紫换牙绯。","人中巧宦谁知此，好向天街插翅飞。"]},{"t":"朱叔召遗文官花二绝句 其二","f":"七言绝句","c":["绿心变却初时白，紫色由来昨夜朱。","学得文官何足道，但堪花径骇僮奴。"]},{"t":"再赋 其一","f":"七言绝句","c":["不用风人怨绿衣，身兼魏紫与潜绯。","司花直为文官地，可忍春残一片飞。"]},{"t":"再赋 其二","f":"七言绝句","c":["解褐方闻上玉除，宠光转眼叠金朱。","大夫不博乔松贵，嘉橘千头也作奴。"]},{"t":"景卢蠙洲","f":"五言绝句","c":["芳洲编地志，老蚌隐澄湾。","轩槛今清绝，全胜合浦还。"]},{"t":"蠙桥","f":"五言绝句","c":["堤长交柳荫，桥狭束荷香。","掩户回逋客，凭栏狎漫郎。"]},{"t":"索笑亭思景严二绝句 其一","f":"五言绝句","c":["往日江梅发，巾车数数来。","自今花索笑，不复共衔杯。"]},{"t":"索笑亭思景严二绝句 其二","f":"五言绝句","c":["常棣春来减，人如折脚铛。","倚栏思旧事，老眼泪纵横。"]},{"t":"次韵景卢赏梅","f":"五言律诗","c":["曲坞梅藏白，东皇解出奇。","不嫌歌板闹，直与酒尊宜。","倚竹盟三友，凌风粲一枝。","清标何水部，千古说能诗。"]},{"t":"石鼓诗","f":"七言古诗","c":["天作高山太王荒，鸑鷟一鸣周剪商。","郏鄏卜年大蒐讲，诸侯敛衽尊天王。","六月中兴绳祖武，平荡犬戎恢境土。","石崖可凿诗可镌，千载神光薄西浒。","橐驼挽入大梁都，璧水湛湛河出图。","中间两鼓备章句，日惟丙申不模糊。","左骖秀弓射麋豕，有鳑有□君子渔。","光和石经屹相望，诅楚登峄非吾徒。","辛壬癸甲雁分翅，桥门观者堵墙如。","星沉东壁干戈起，首下足上天倒置。","景钟糜碎九鼎飞，王迹皇风吁扫地。","群胡扛石徙幽燕，兵车乱载包无毡。","敲火砺角小小尔，为础为砧多历年。","宣和殿中图复古，冠以车攻次十鼓。","韩诗欧跋尽兼收，云章剖判定鱼鲁。","先君辛苦朔方归，文犀拱璧弃弗携。","一编十袭自鐍秘，更有司马凤翔碑。","我生不辰今已老，岐阳三雍身不到。","匆匆使虏接淅行，在耶亡耶问无报。","整齐篆籀饰牙签，简撮篇咏劳穷探。","致主有心歌小雅，汗颜无术下登三。"]},{"t":"丙申腊二十五日落一左齿","f":"七言绝句","c":["行年六十已中枯，雪映衰髯岁且除。","一齿骤然离左辅，益怜大嚼远庖厨。"]},{"t":"野处孔雀为狸所毙","f":"七言律诗","c":["远程万里起南溟，文采葳蕤掩画屏。","展翼来朝金翠晃，竦身轻举鹊乌停。","园中但有辟蛇法，山下相望瘗鹤铭。","野鹜家鸡随处有，孽狐何事独淫刑。"]},{"t":"过濠上","f":"五言绝句","c":["心随溪水清，目逆岫云生。","不惮躧芳屐，桥南鸥乞盟。"]},{"t":"豹岩之北脩竹数亩中有丛冢数十百处皆绍兴末年所寄予得此地先定规抚某处起亭榭某处植花木七八年间成畦径矣所寄之榇愿移者从之不强也作噩之春有姓淡人来启菆卜日携锸掘土数尺败棺俱在朽骨为土所蚀颇亦不具皆包裹而去后数日忽诉于县于州于外台追问證治踰月始定今不复塞其故穴欲使孙曾知之故作此诗","f":"五言古诗","c":["未央长乐宫，中有樗里墓。","沈沈天子居，咫尺穴狐兔。","乃知古圣人，如天覆下土。","虽袒裼裸裎，四目曾不顾。","贤哉季武子，杜殡迫西庑。","堂皇步武接，松槚暗钟鼓。","桃茢不屏除，刍灵许来祔。","忌讳后愈多，今人不如古。","曹瞒好发丘，凶德比夷虏。","掩骼埋其胔，人当事斯语。","我老得归田，买山因学圃。","郁郁琅玕林，丛冢不知数。","岂忍去枯骨，为我展杖屦。","恣其笋侵疆，不使种瓜瓠。","花木列四旁，亭榭亦回护。","数年畦径成，或徙或如故。","尚有犷悍人，珥笔巧诬诉。","无言事自明，有物众所睹。","旧圹今弗堙，朽木且支柱。","尚恐妄男子，轻传市中虎。","书事示孙曾，无心觅佳句。"]},{"t":"席上见姚泉寿母诸子求诗","f":"五言绝句","c":["潘舆随五采，三釜古今荣。","兰玉盈阶砌，追攀千佛名。"]},{"t":"董伯鲁以诗送川海棠用韵答之","f":"五言绝句","c":["花栽趁上春，重趼疲双足。","何日对仙姿，分题同刻烛。"]},{"t":"次韵景卢题龟巢","f":"七言律诗","c":["拙速谁云胜巧迟，新亭结罢得能奇。","细看远水兼天净，可但中秋观月宜。","出郭自欣三径乐，枕流今有几人痴。","巢莲千岁同藏六，一笑泥涂曳尾龟。"]},{"t":"三月十六日龟巢观月渭师携宠同赏后两日大雨复作景卢有诗同其韵","f":"七言律诗","c":["潜鳞故故上钩迟，翠袖凭栏自一奇。","半夜醉归闲有趣，一年春尽事如宜。","盍簪何惮再三渎，览镜堪嗟六十痴。","已办寻盟临斫鲙，不将可否问蓍龟。"]},{"t":"四月十三日流杯次景卢韵寄渭师","f":"五言律诗","c":["今年无好雨，曲水未胜杯。","谁伴山翁醉，难令俗客陪。","青苔迎马入，绿柳送莺来。","纵步濠梁上，垂缗更乐哉。"]},{"t":"流杯同景裴韵","f":"七言律诗","c":["三春少雨未行觞，槐影交加更漏长。","半夜水来山涧满，四檐竹密酒尊凉。","新亭方作龟巢叶，画栋何妨燕语梁。","满引三觥拚一醉，老来真个惜时光。"]},{"t":"流杯次日连雨渭师有诗次其韵","f":"七言律诗","c":["入夏浓云日夕昏，举头烟雨暗前村。","风随重客清葵扇，月为佳人射翠樽。","依旧建瓴攲屋角，几番携杖失溪痕。","小枰已在纱窗下，欲把明琼看倒盆。"]},{"t":"再答","f":"七言律诗","c":["投老无能千虑昏，归田浸久使令村。","长因步月成三影，难得朋云共一樽。","水涨溪桥孤钓隐，雨侵山径洗鞸痕。","寓公在此宁黔突，会有容光照覆盆。"]},{"t":"景卢开尊阻雨展日复用前韵寄之","f":"七言律诗","c":["逐妇鸣鸠急定昏，不堪烟霭弄千村。","掩关尽日资筇杖，改席何时对瘿樽。","云暗松皮多节目，雨伤梨颊有瘢痕。","溪神若也心无妒，迎出常娥照玉盆。"]},{"t":"雨中排闷","f":"七言律诗","c":["饭牛戴笠牧童昏，安得斜阳过别村。","户外涎蜗行半壁，床头渴鼠侧空樽。","花残莺老浑如梦，水到渠成不见痕。","天意未晴人未饮，家奴款曲办籸盆。"]},{"t":"再赋","f":"七言律诗","c":["月在云中破镜昏，几时清影散林村。","杖藜难去寻渔艇，洗盏无因续蚁樽。","竹叶弄风添秀色，榴花带雨露啼痕。","不如暮捲珠帘醉，唤取佳人笑拊盆。"]},{"t":"庚子山居采茶有感","f":"五言古诗","c":["忆昔采茶时，雨后山蹊湿。","鹰爪喜盈襜，蟹眼思朝汲。","归路取盘洲，下昃行踪急。","珠汗透裳衣，更换登梯级。","徙倚曲栏竿，鸣雁圆沙集。","晚景不胜春，寒气潜相袭。","诘旦傍装台，攲侧人扶立。","舆疾望医来，谁煮青黏汁。","举案念齐眉，幻泡何嗟及。","重过故园门，不忍携筇入。","引领顾前丘，空对旗枪泣。"]},{"t":"一春置酒必苦风雨今日幸晴而景卢有行色","f":"七言律诗","c":["一春风雨厄游遨，此际开樽始解嘲。","恰恰鸣禽藏柳陌，欣欣嫩叶迸花梢。","离筵欲动愁分袂，胜日何妨剩出郊。","燕寝香凝公事了，频将书札问龟巢。"]},{"t":"次景裴席上韵","f":"七言律诗","c":["桃李纷纷已半春，海棠睡觉晚妆新。","龟巢剩有千般景，琼报浑无一点尘。","酒未举杯风逐客，诗方拈笔雨催人。","从今只拣晴和日，草草杯盘勿厌频。"]},{"t":"用景卢诸公诗轴韵招监司太守","f":"七言律诗","c":["浅白轻红笑倚门，何须雪夜忆前村。","韶光定入诗人句，胜事难逢俗子言。","风振绣衣须命驾，云随皂盖欲窥园。","人生易老愁春老，问柳寻花故事存。"]},{"t":"景卢数日枕疾复用前韵","f":"七言律诗","c":["半载悠悠只闭门，不知红绿遍千村。","山川满目供衰境，桃李成蹊出怨言。","可惜花飞聊洗盏，何期雨作阻行园。","车公不出须重讲，检校芳菲心兴存。"]},{"t":"答景裴","f":"七言律诗","c":["春来剥啄少登门，涩雨悭风笑我村。","桥上垂纶装好梦，花边倚杖记前言。","长杨美竹虽当户，语燕流莺不到园。","此会明年千里隔，诗筒犹有置邮存。"]},{"t":"席上遗景卢","f":"七言律诗","c":["白发归休阅半生，棣华酬唱得娱情。","双旌欲指闽中去，三径谁同月下行。","蕙帐风清知鹤怨，蘋洲波细忆鸥盟。","新坛留慰人千里，把盏相思泪睫横。"]},{"t":"枕上示景卢 其一","f":"七言绝句","c":["朱轓皂盖有行期，暮景无情惜别离。","枕疾半旬乖语笑，急风吹雨泪垂垂。"]},{"t":"枕上示景卢 其二","f":"七言绝句","c":["南憩番禺北抵燕，片帆西上驻荆门。","平生不作东瓯梦，荔子丹时念灌园。"]},{"t":"答太守谢牡丹","f":"七言律诗","c":["华发归来不记春，优游学圃傲江村。","已欣胜日临千骑，漫折香霞佐一尊。","对竹便当寻曲水，藏花那肯效慈恩。","行厨若有真消息，奔走畦丁急扫门。"]},{"t":"怀景卢","f":"七言律诗","c":["菖蒲节近暑风高，常棣丛疏月影交。","清夜不曾空鹤帐，浮生何幸老龟巢。","酒杯独引今无侣，书卷闲开共苦抄。","想得公堂凫鹜退，须怀西坞欠诛茅。"]},{"t":"答徐守 其一","f":"七言绝句","c":["改日开尊已十成，冬曦特地晚来晴。","江梅独报春消息，应笑群花太薄情。"]},{"t":"答徐守 其二","f":"七言绝句","c":["不教丝竹沸层台，促席飞谈怀抱开。","夜半梦回聊趁韵，愧无好语答琼瑰。"]},{"t":"排闷","f":"五言律诗","c":["数日雷中雨，凝寒懒举头。","出游闲豹舄，危坐索狐裘。","怕冷杯常执，扶衰药屡投。","满园冰木稼，天遣阿谁忧。"]},{"t":"雪中叹","f":"七言律诗","c":["连绵春雪助凶年，平地盈庭大可叹。","词客罢吟梅散漫，园夫惭报竹平安。","乌鸢腹馁飞穿屋，牛马毛寒病倚栏。","天意欲添人殍野，四时玉烛古来难。"]},{"t":"答裴弟","f":"七言律诗","c":["常棣成阴慰暮年，困人春雪好长叹。","闭门终日诗频和，伏枕盈旬病未安。","已遣携锄移竹径，更思杖策整花栏。","饱闻冰下游鱼跃，所恨双溪一笑难。"]},{"t":"忆昔","f":"七言绝句","c":["跨马春衢袅翠鞭，垂纶圯下解渔船。","霞飞绮散无踪迹，依旧清霄月在川。"]},{"t":"寄景卢时往豫章","f":"七言律诗","c":["闻得荼□语牡丹，蜂回蝶散恨春残。","西山拄笏晨光爽，北海空尊夜漏寒。","徐孺堂中同下榻，滕王阁外久凭栏。","归来已失兰亭集，照眼榴花待细看。"]},{"t":"辛幼安稼轩","f":"七言律诗","c":["济时方略满心胸，卜筑依城乐事重。","岂是求田谋万顷，聊因学圃问三农。","高牙暂借藩维重，燕寝未须归兴浓。","且为君王开再造，它年植杖得从容。"]},{"t":"盘洲杂韵上 盘洲","f":"五言绝句","c":["曲曲盘洲径，苍崖路几层。","翠微深处坐，閒话正留僧。"]},{"t":"盘洲杂韵上 双溪","f":"五言绝句","c":["清溪夹桃径，玉洞万株春。","为有双溪误，渔人休问津。"]},{"t":"盘洲杂韵上 日涉门","f":"五言绝句","c":["小圃固日涉，柴门常自关。","此心无一事，应共白云閒。"]},{"t":"盘洲杂韵上 索笑亭","f":"五言绝句","c":["虎溪当日事，此处可留踪。","相逢索一笑，何必话中峰。"]},{"t":"盘洲杂韵上 绿萼梅","f":"五言绝句","c":["香浓逾粉质，碧腻素娥妆。","若使羊郎见，仙姿应并芳。"]},{"t":"盘洲杂韵上 鸳鸯梅","f":"五言绝句","c":["疏枝分异蕊，孤干列鸳鸯。","应知为赠远，异样缀清装。"]},{"t":"盘洲杂韵上 红梅","f":"五言绝句","c":["绽玉闻欺雪，含章妒绛纱。","不同桃李种，粲煞赤城霞。"]},{"t":"盘洲杂韵上 腊梅","f":"五言绝句","c":["篱菊初残后，疏香忽傲霜。","一枝冲腊绽，紫瑰列金房。"]},{"t":"盘洲杂韵上 黄梅","f":"五言绝句","c":["未结金丸果，先吐黄芽花。","却误林和靖，翻疑姚氏家。"]},{"t":"盘洲杂韵上 芝径","f":"五言绝句","c":["金茎岂受尘，三秀已通神。","不竞铜池瑞，逢兰肯卜邻。"]},{"t":"盘洲杂韵上 种秫仓","f":"五言绝句","c":["种秫无多子，犹胜避俗翁。","尽将供酿具，不复用青铜。"]},{"t":"盘洲杂韵上 芝泉","f":"五言绝句","c":["美瑞山祇管，幽泉地脉通。","漱甘冰熨齿，短绠走溪童。"]},{"t":"盘洲杂韵上 草塘","f":"五言绝句","c":["茸茸春草茁，碧水涌方塘。","入梦无佳句，看云忆对床。"]},{"t":"盘洲杂韵上 鱼台","f":"五言绝句","c":["掩关麾俗子，裂网禁畦丁。","台下鱼相贺，溪边人独醒。"]},{"t":"盘洲杂韵上 兑桥","f":"五言绝句","c":["桥横桑下涧，望处极西郊。","有客同飞盖，何人伴结茅。"]},{"t":"盘洲杂韵上 泛杯岩","f":"五言绝句","c":["酒进鸬鹚杓，花随翡翠盘。","岩边多怪石，岩下有奔湍。"]},{"t":"盘洲杂韵上 九曲","f":"五言绝句","c":["风轻杯荡漾，岸曲水逶迤。","遇坎亦可喜，倒行羞接篱。"]},{"t":"盘洲杂韵上 棕亭","f":"五言绝句","c":["乞得栟榈叶，都将当屋茅。","青青夸药申，可怕杜陵嘲。"]},{"t":"盘洲杂韵上 一咏亭","f":"五言绝句","c":["有水足浮醴，宁拘秋与春。","共将诗拟古，不必语惊人。"]},{"t":"盘洲杂韵上 小垂手","f":"五言绝句","c":["醉袖起如舞，翩然三岛仙。","约君为石友，伴我傲林泉。"]},{"t":"盘洲杂韵上 醒酒石","f":"五言绝句","c":["名高牛氏品，地接燕儿窠。","有客图沉醉，翻嫌石是魔。"]},{"t":"盘洲杂韵上 墨沼","f":"五言绝句","c":["凿地肖风轮，洗云吞月扇。","败墨起缁尘，山阴劳北面。"]},{"t":"盘洲杂韵上 既醉亭","f":"五言绝句","c":["酒半兴方浓，瓶空罍弗耻。","更看一筹输，各尽三觥醉。"]},{"t":"盘洲杂韵上 溪帘","f":"五言绝句","c":["雨过溪添绿，横澜自在流。","水精帘欲捲，何处著银钩。"]},{"t":"盘洲杂韵上 可止亭","f":"五言绝句","c":["循除泉漱石，改席酒分船。","到此须知止，行前将坠渊。"]},{"t":"盘洲杂韵上 鹅池","f":"五言绝句","c":["路转左画方，水来斜中矩。","不解写黄庭，倚筇看白羽。"]},{"t":"盘洲杂韵上 流瀑","f":"五言绝句","c":["高坡势建瓴，触石惊涛沸。","入耳转声清，庐峡参差是。"]},{"t":"盘洲杂韵上 薝卜涧","f":"五言绝句","c":["夹涧荣薝卜，倚竹颜如玉。","溪鱼大上时，临流香可掬。"]},{"t":"盘洲杂韵上 菊澨","f":"五言绝句","c":["夕英色衰落，小摘尚盈襟。","错会离骚意，元无满地金。"]},{"t":"盘洲杂韵上 末利菊","f":"五言绝句","c":["化工将末利，改作寿潭花。","零露团佳色，鹅黄自一家。"]},{"t":"盘洲杂韵上 双溪堂","f":"五言绝句","c":["溪光摇四壁，瓦影落中流。","洗耳百闻寂，清心千虑休。"]},{"t":"盘洲杂韵上 舣斋","f":"五言绝句","c":["随波堪泛宅，因壑遂藏舟。","坐稳无维楫，任他风打头。"]},{"t":"盘洲杂韵上 云叶","f":"五言绝句","c":["支机何代石，风截秋云根。","一叶下人境，坐令台榭尊。"]},{"t":"盘洲杂韵上 啸风岩","f":"五言绝句","c":["于菟啸空山，万窍寒风出。","堤防飞将军，汉箭有神物。"]},{"t":"盘洲杂韵上 蜂房","f":"五言绝句","c":["石是蜂窠变，蜂来有处藏。","不须开户牖，薜荔为穿房。"]},{"t":"盘洲杂韵上 磐矶","f":"五言绝句","c":["有竿不见纶，无纶焉用饵。","终日坐钓矶，旁人笑儿戏。"]},{"t":"盘洲杂韵上 问柳桥","f":"五言绝句","c":["濡毫求露柱，堕履望奇书。","问讯缘溪柳，新条可拂裾。"]},{"t":"盘洲杂韵上 凤柳","f":"五言绝句","c":["春情百尺牵，午影三眠过。","修眉漫成颦，细腰谁类我。"]},{"t":"盘洲杂韵上 蓼岸","f":"五言绝句","c":["岸蓼花如糁，残霞照晚汀。","不教资曲蘖，留得隐鵁鶄。"]},{"t":"盘洲杂韵上 碧芦步","f":"五言绝句","c":["津头晚风急，攲倒一丛芦。","宿雁逢清泚，飞来作画图。"]},{"t":"盘洲杂韵上 西浒","f":"五言绝句","c":["春冯西浒窗，夏卧西浒榻。","待月最宜秋，探梅还度腊。"]},{"t":"盘洲杂韵上 扁舟","f":"五言绝句","c":["非厌人间事，不携西子游。","聊将去越意，指此作扁舟。"]},{"t":"盘洲杂韵上 飞庐","f":"五言绝句","c":["浮家今得计，举棹疾于飞。","一笑儿童舞，芳莲当妓围。"]},{"t":"盘洲杂韵上 采莲舟","f":"五言绝句","c":["圣得三峰藕，刳为一瓣莲。","著身犹不稳，何用济长川。"]},{"t":"盘洲杂韵上 彩鹢","f":"五言绝句","c":["兴来飞画舸，泛泛水中凫。","绿皱移歌扇，红鲜迓酒壶。"]},{"t":"盘洲杂韵上 饭牛亭","f":"五言绝句","c":["冬耕春复犁，麦秀禾方插。","少放牧儿休，莫教牛力乏。"]},{"t":"盘洲杂韵上 西畴","f":"五言绝句","c":["代耕荒幼学，投老乐归田。","卤莽人之罪，丰凶勿怨天。"]},{"t":"盘洲杂韵上 土湖","f":"五言绝句","c":["波涛送客帆，松竹围僧舍。","野趣望中来，西湖当减价。"]},{"t":"盘洲杂韵上 石巷","f":"五言绝句","c":["一丘封竹弟，万石齿金昆。","收拾甲乙品，庄严可款门。"]},{"t":"盘洲杂韵上 有竹轩","f":"五言绝句","c":["前身岂汲直，枉尺天所难。","贤哉耐久朋，结盟同岁寒。"]},{"t":"盘洲杂韵上 斑竹","f":"五言绝句","c":["帝子登湘岸，临风粉泪弹。","梨花多少雨，点点透琅玕。"]},{"t":"盘洲杂韵上 紫竹","f":"五言绝句","c":["拾青容色混，著紫宠光偏。","幽径留风月，行多履易穿。"]},{"t":"盘洲杂韵上 方竹","f":"五言绝句","c":["体方如就矩，干直匪从绳。","杖有削圜厄，提携先摸棱。"]},{"t":"盘洲杂韵上 人面竹","f":"五言绝句","c":["怪奇存相法，妍丑出天真。","此君无二貌，正是葛天民。"]},{"t":"盘洲杂韵上 猫头竹","f":"五言绝句","c":["穹枝回凤尾，健笋迸猫头。","安得真致此，勿为群鼠羞。"]},{"t":"盘洲杂韵上 慈竹","f":"五言绝句","c":["义居传九世，瑞物记三荆。","何似同根竹，春风一死生。"]},{"t":"盘洲杂韵上 笛竹","f":"五言绝句","c":["蕲产名天下，含飔别样青。","中郎如一见，应不数柯亭。"]},{"t":"盘洲杂韵上 箭竹","f":"五言绝句","c":["美箭东南出，成林地不悭。","禽胡如有将，寄与定天山。"]},{"t":"盘洲杂韵上 洗心阁","f":"五言绝句","c":["餐霞吞沆瀣，一吸千顷湖。","默坐更深省，心尘今有无。"]},{"t":"盘洲杂韵上 橘友亭","f":"五言绝句","c":["倚楹歌橘颂，巡圃款甘林。","更待商山老，于斯朋盍簪。"]},{"t":"盘洲杂韵上 绣橘","f":"五言绝句","c":["后皇权植物，奴婢遍江干。","绣蹙一林橘，高擎黄玉团。"]},{"t":"盘洲杂韵上 脆橙","f":"五言绝句","c":["谓橘不盈握，胜橙颛进皮。","香齑难共捣，遮莫蟹螯持。"]},{"t":"盘洲杂韵上 金橘","f":"五言绝句","c":["朱襦千里变，金弹一分增。","入口蜜相避，怀归谁不能。"]},{"t":"盘洲杂韵上 罗甘","f":"五言绝句","c":["罗包肌理细，霜颗辅车香。","封殖贵濒水，踰淮非我乡。"]},{"t":"盘洲杂韵上 常棣径","f":"五言绝句","c":["已废蓼莪篇，难荒常棣径。","步屐不思归，共看花弄影。"]},{"t":"盘洲杂韵上 花信亭","f":"五言绝句","c":["时时风报信，处处雨催妆。","大赉一年景，均输万斛香。"]},{"t":"盘洲杂韵上 牡丹","f":"五言绝句","c":["绮席偏宜昼，香霞独占春。","洛阳荆棘久，谁是惜花人。"]},{"t":"盘洲杂韵上 勺药","f":"五言绝句","c":["名标溱洧赠，根自广陵分。","所欠盘盂玉，黄楼尽不群。"]},{"t":"盘洲杂韵上 丹桂","f":"五言绝句","c":["无癖不誉儿，有诗非责子。","丹桂几枝芳，对之空颡泚。"]},{"t":"盘洲杂韵上 瑞香","f":"五言绝句","c":["紫苞杨柳叶，奇绝锦熏笼。","香气阗襟袖，清尊为汝空。"]},{"t":"盘洲杂韵上 白山茶","f":"五言绝句","c":["自读文成赋，经营巧作难。","涪翁真溢美，何似鹤头丹。"]},{"t":"盘洲杂韵上 白榴","f":"五言绝句","c":["耻上舞裙带，愿依九琳窗。","韶颜今换骨，阿措便心降。"]},{"t":"盘洲杂韵上 末利","f":"五言绝句","c":["肤瑩过凝脂，香浓远随步。","应有看花人，入园心见妒。"]},{"t":"盘洲杂韵上 素馨","f":"五言绝句","c":["繁盛闽南粤，潜藏霜雪天。","素云生宝髻，剩馥借龙涎。"]},{"t":"盘洲杂韵上 木犀","f":"五言绝句","c":["逋客敢欺桂，秋岩曾遣风。","古香吹一再，如到广寒宫。"]},{"t":"盘洲杂韵上 文官花","f":"五言绝句","c":["破白便怀青，纡朱旋著紫。","鼎鼎一春忙，浮荣均梦蚁。"]},{"t":"盘洲杂韵上 聚八仙","f":"五言绝句","c":["圆整装花蕊，周遭列饮仙。","琼英难上僭，簇蝶不同年。"]},{"t":"盘洲杂韵上 衮绣毬","f":"五言绝句","c":["流苏团小蝶，伯仲聚仙花。","衮绣名非是，瑶琨未足誇。"]},{"t":"盘洲杂韵上 水桅","f":"五言绝句","c":["鲜支形相小，石罅解蟠根。","香凑芝兰室，居便水月村。"]},{"t":"盘洲杂韵上 重杏","f":"五言绝句","c":["重英迷宿雨，巧笑聘春风。","寿汝一卮酒，勿嫌肌太红。"]},{"t":"盘洲杂韵上 紫薇","f":"五言绝句","c":["十年三雁序，接翅紫微垣。","花下哦前什，难酬明主恩。"]},{"t":"盘洲杂韵上 荼蘼","f":"五言绝句","c":["青条散蛟螭，素艳欺琼玖。","体薰尘外香，骨醉壶中酒。"]},{"t":"盘洲杂韵上 玉珑松","f":"五言绝句","c":["品轧酴醾架，名疑雾淞花。","□将□假借，可但鄙金沙。"]},{"t":"盘洲杂韵上 山茶","f":"五言绝句","c":["平泉穷胜事，南守送名花。","寓意惩多爱，劳人召怨嗟。"]},{"t":"盘洲杂韵上 黄蔷薇","f":"五言绝句","c":["彤阙收红绶，金门赐鞠衣。","若无纤刺罥，一摘便须稀。"]},{"t":"盘洲杂韵上 红蕉","f":"五言绝句","c":["岭外花无数，分移颇历年。","破除猩血染，舒卷蜀城笺。"]},{"t":"盘洲杂韵上 海仙","f":"五言绝句","c":["人来认海棠，却讶枝条弱。","嫩蕊不胜春，生怕东风恶。"]},{"t":"盘洲杂韵上 绣带","f":"五言绝句","c":["蜀艳停针久，柔荑著意描。","五文萦色线，百宝簇芳腰。"]},{"t":"盘洲杂韵上 豆蔻花","f":"五言绝句","c":["冶叶拥香苞，盈盈二月交。","相思意安在，试去想花梢。"]},{"t":"盘洲杂韵上 丽春","f":"五言绝句","c":["纤莛小作罂，瘦壳元无粟。","色丽品少双，诗成看未足。"]},{"t":"盘洲杂韵上 长春","f":"五言绝句","c":["四季花长发，朝朝得细看。","绛英能受暑，绿刺更禁寒。"]},{"t":"盘洲杂韵上 水仙","f":"五言绝句","c":["龙宫陈酒器，金盏白银台。","欲结埙篪伴，无踰绿萼梅。"]},{"t":"盘洲杂韵上 剪春罗","f":"五言绝句","c":["巧剪鲛绡碎，深涂绛蜡匀。","残英枝上隐，踰月逞鲜新。"]},{"t":"盘洲杂韵上 玉簪","f":"五言绝句","c":["月娥新琢玉，何夕忽遗簪。","斜插风鬟湿，蟾宫底处寻。"]},{"t":"盘洲杂韵上 麝萱","f":"五言绝句","c":["手撚雏莺羽，鼻参香麝脐。","千忧何处散，芳径酒争携。"]},{"t":"盘洲杂韵上 玉灯","f":"五言绝句","c":["叶如薏苡长，花比金灯白。","一簇蕊宫仙，银灯臧与获。"]},{"t":"盘洲杂韵上 斗日红","f":"五言绝句","c":["红英斗日开，暮落锦成堆。","不藉西风力，孤根委草莱。"]},{"t":"盘洲杂韵上 佛桑","f":"五言绝句","c":["展叶柔桑沃，装丛醉缬繁。","定应西域到，略不耐轻寒。"]},{"t":"盘洲杂韵上 木芙蓉","f":"五言绝句","c":["川陆有芙蓉，名同物不同。","采江搴木句，作么误韩公。"]},{"t":"盘洲杂韵上 黄拒霜","f":"五言绝句","c":["芳林秋冷落，木末改黄裳。","可笑名虚忝，何曾拒得霜。"]},{"t":"盘洲杂韵上 小黄葵","f":"五言绝句","c":["拂金铺细靥，骑鹄堕新翎。","花小也倾日，芒寒犹聚星。"]},{"t":"盘洲杂韵上 金凤","f":"五言绝句","c":["九苞滋雨露，五采烛轩楹。","奉送归丹穴，朝阳幸一鸣。"]},{"t":"盘洲杂韵上 鸡冠","f":"五言绝句","c":["未观金距斗，已怪左轮殷。","一夜风霜作，垂头急挂冠。"]},{"t":"盘洲杂韵上 石竹","f":"五言绝句","c":["蘤红蜂好齧，路细麝来眠。","若也栽幽处，踰冬色不蔫。"]},{"t":"盘洲杂韵上 黄莺儿","f":"五言绝句","c":["鹂庚翻柳去，拾羽渍轻花。","战战枝如压，无风势亦斜。"]},{"t":"盘洲杂韵上 真珠","f":"五言绝句","c":["细簇盘洲岸，初惊合浦还。","娉婷邀十斛，惜取买青山。"]},{"t":"盘洲杂韵上 鼓子","f":"五言绝句","c":["抽蔓类牵牛，含芳伍萱草。","上上不知休，高柯厌缠绕。"]},{"t":"盘洲杂韵上 金钱","f":"五言绝句","c":["炉炽阴阳炭，金钱满地流。","何人能点铁，笑觅富民侯。"]},{"t":"杂咏下 金灯","f":"五言绝句","c":["灯焰既埋光，幽蕤不露黄。","阿谁驴唤狗，为我问花王。"]},{"t":"杂咏下 百结","f":"五言绝句","c":["体轻难受雨，枝软不禁风。","全赖结蟠力，能超造化功。"]},{"t":"杂咏下 后庭花","f":"五言绝句","c":["月满临春阁，云随张丽华。","隔江虽度曲，破国不因花。"]},{"t":"杂咏下 凌霄","f":"五言绝句","c":["天借凭依便，云霄若可凌。","莫教风拔木，却羡水飘萍。"]},{"t":"杂咏下 杜鹃花","f":"五言绝句","c":["山深啼杜宇，溅血染花心。","阆苑未归去，不妨留鹤林。"]},{"t":"杂咏下 玉胡蝶","f":"五言绝句","c":["赞皇褒簇蝶，京洛古来希。","一阵雄风起，穿林粉翅飞。"]},{"t":"杂咏下 苔","f":"五言绝句","c":["赤憎宾舍满，雅称落花留。","纵使金钱好，如何买断秋。"]},{"t":"杂咏下 虞美人草","f":"楚辞体","c":["尤物钟芳草，虞兮柰若何。","动摇缘体弱，非是感悲歌。"]},{"t":"杂咏下 睡足亭","f":"五言绝句","c":["露重宿妆凝，地偏春睡足。","卜夜到横参，却须高举烛。"]},{"t":"杂咏下 黄海棠","f":"五言绝句","c":["汉宫娇半额，雅淡称花仙。","天与温柔态，妆成取次妍。"]},{"t":"杂咏下 垂丝海棠","f":"五言绝句","c":["脉脉似崔徽，朝朝长看地。","谁能解倒悬，扶起云鬟坠。"]},{"t":"杂咏下 孤松","f":"五言绝句","c":["昂霄苍鬣五，独立几寒暑。","不肯在鸡群，自然羞哙伍。"]},{"t":"杂咏下 菱湾","f":"五言绝句","c":["食芹知献君，嗜芰不忘亲。","大节全忠孝，劳心思古人。"]},{"t":"杂咏下 芡曲","f":"五言绝句","c":["芡槃平羃水，雁喙饱吞风。","剖蚌珠惊坐，清谈拳屡空。"]},{"t":"杂咏下 林珍亭","f":"五言绝句","c":["主林时献供，它壤昔移根。","秋后收梨栗，倾奁得弄孙。"]},{"t":"杂咏下 樱桃","f":"五言绝句","c":["园官来献孰，万颗滴阶红。","绿李高名品，须知论未公。"]},{"t":"杂咏下 蒲萄","f":"五言绝句","c":["虺蔓奋长须，累累明月珠。","休传酿酒法，万一误分符。"]},{"t":"杂咏下 雪梨","f":"五言绝句","c":["魁然饤坐珍，落刃雪分身。","酒渴思吞海，加笾纵臾人。"]},{"t":"杂咏下 鹅梨","f":"五言绝句","c":["新鹅借颜色，甘蜜添滋味。","忆得赏花时，阑干带春泪。"]},{"t":"杂咏下 林禽","f":"五言绝句","c":["蒙润碧千颗，迎曦红半颊。","阅古憩鹅池，牵连青李帖。"]},{"t":"杂咏下 竹村","f":"五言绝句","c":["一任笋侵疆，何防鞭碍道。","千户广侯封，三家结村保。"]},{"t":"杂咏下 竹屋","f":"五言绝句","c":["栋梁无一木，眼底尽龙孙。","千亩清阴合，出门人灌园。"]},{"t":"杂咏下 灌园亭","f":"五言绝句","c":["好手善和羹，非才当抱瓮。","加点苜蓿盘，丁宁及时种。"]},{"t":"杂咏下 西瓜","f":"五言绝句","c":["万里随肤使，分留三十年。","甘棠遗爱在，一见一潸然。"]},{"t":"杂咏下 罂粟","f":"五言绝句","c":["美体亚群花，千罂倒储粟。","饮客醍醐浆，可以代醽醁。"]},{"t":"杂咏下 琼报亭","f":"五言绝句","c":["珍物再三投，英琼修永好。","以兹君子德，不作众人报。"]},{"t":"杂咏下 木瓜","f":"五言绝句","c":["硕果宣城得，花肤易地无。","上楼要脚健，不假瘦藤扶。"]},{"t":"杂咏下 矮桃","f":"五言绝句","c":["结子卑枝繁，成蹊长策舍。","饱杀驺侏儒，谁牵果下马。"]},{"t":"杂咏下 昆崙桃","f":"五言绝句","c":["满树鸠盘茶，曾开胜锦花。","夺胎春薄相，刻画搅诗家。"]},{"t":"杂咏下 朝天李","f":"五言绝句","c":["长柯浑直上，茂叶不横生。","缟夜心倾藿，朝天荷美名。"]},{"t":"杂咏下 破核李","f":"五言绝句","c":["苇绡攲鼠穴，翠质临螬井。","自破核不钻，通行冠可整。"]},{"t":"杂咏下 嘉庆子","f":"五言绝句","c":["雪艳燕脂萼，京都核远来。","游人初识面，不作李花猜。"]}]};